  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_flow_form_type` (`form_type`,`form_key`),
  KEY `idx_approval_flow_enable` (`enable`),
  KEY `idx_approval_flow_created_at` (`created_at`),
  KEY `idx_approval_flow_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='流程主表';

