DROP TABLE IF EXISTS `approval_node_approver`;

CREATE TABLE `approval_node_approver` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT 'PK=approval_node.id(共享主键)',
  `flow_version_id` bigint unsigned NOT NULL COMMENT '所属流程版本ID',
  `approval_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'AUTO_PASS' COMMENT '审批类型',
  `multi_approver_mode` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '多审批人模式(ALL/ANY/SEQUENTIAL)',
  `empty_approver_action` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'AUTO_PASS' COMMENT '空审批人处理',
  `fallback_approver` bigint unsigned DEFAULT NULL COMMENT '兜底审批人ID',
  `same_submitter_action` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'SKIP' COMMENT '提交人本人处理(SKIP/ALLOW/ASSIGN_SUPERIOR)',
  `approver_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批人类型(MEMBER/SUPERIOR/ROLE 等)',
  `approver_direction` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'BOTTOM_UP' COMMENT '解析方向',
  `cc_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '抄送人类型',
  `cc_list` text COLLATE utf8mb4_unicode_ci COMMENT '抄送人JSON数组',
  `approver_list` text COLLATE utf8mb4_unicode_ci COMMENT '审批人JSON数组(按approver_type不同解析)',
  `pass_post_config` text COLLATE utf8mb4_unicode_ci COMMENT '通过后操作配置JSON(字段更新+webhook)',
  `reject_post_config` text COLLATE utf8mb4_unicode_ci COMMENT '驳回后操作配置JSON',
  `field_permissions` text COLLATE utf8mb4_unicode_ci COMMENT '字段权限JSON数组',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_approval_node_approver_flow_version_id` (`flow_version_id`),
  KEY `idx_approval_node_approver_created_at` (`created_at`),
  KEY `idx_approval_node_approver_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=98 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='节点审批人配置(PK 与 ApprovalNode 共享主键)';

