  `flow_version_id` bigint unsigned NOT NULL COMMENT '所属流程版本ID',
  `condition_config` text COLLATE utf8mb4_unicode_ci COMMENT '条件配置JSON(分支匹配规则)',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_approval_node_condition_flow_version_id` (`flow_version_id`),
  KEY `idx_approval_node_condition_created_at` (`created_at`),
  KEY `idx_approval_node_condition_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=76 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='节点条件配置(PK 与 ApprovalNode 共享主键)';

