DROP TABLE IF EXISTS `approval_node_link`;

CREATE TABLE `approval_node_link` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `flow_version_id` bigint unsigned NOT NULL COMMENT '所属版本ID',
  `from_node_id` bigint unsigned NOT NULL COMMENT '起始节点ID',
  `to_node_id` bigint unsigned NOT NULL COMMENT '目标节点ID',
  `sort` bigint DEFAULT '0' COMMENT '排序',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
