  KEY `idx_approval_node_link_created_at` (`created_at`),
  KEY `idx_approval_node_link_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=75 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='节点连线(流转路径)';

