DROP TABLE IF EXISTS `approval_record`;

CREATE TABLE `approval_record` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `instance_id` bigint unsigned NOT NULL COMMENT '实例ID',
  `task_id` bigint unsigned DEFAULT NULL COMMENT '任务ID(自动通过/拒绝可空)',
  `node_id` bigint unsigned NOT NULL COMMENT '节点ID',
  `node_round` bigint NOT NULL COMMENT '节点轮次',
  `result` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批结果(含AUTO_APPROVED/AUTO_UNAPPROVED合成态)',
  `comment` text COLLATE utf8mb4_unicode_ci COMMENT '审批意见',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_approval_record_instance_id` (`instance_id`),
  KEY `idx_approval_record_created_at` (`created_at`),
  KEY `idx_approval_record_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=66 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='审批操作记录(不可变审计日志)';

