DROP TABLE IF EXISTS `approval_return_back_record`;

CREATE TABLE `approval_return_back_record` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `instance_id` bigint unsigned NOT NULL COMMENT '实例ID',
  `task_id` bigint unsigned NOT NULL COMMENT '触发退回的任务ID',
  `return_to_node_id` bigint unsigned NOT NULL COMMENT '退回到的节点ID',
  `return_reason` text COLLATE utf8mb4_unicode_ci COMMENT '退回原因',
  `return_user_id` bigint unsigned NOT NULL COMMENT '退回操作人ID',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_approval_return_back_record_instance_id` (`instance_id`),
  KEY `idx_approval_return_back_record_created_at` (`created_at`),
  KEY `idx_approval_return_back_record_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='退回记录';

DROP TABLE IF EXISTS `approval_task`;

CREATE TABLE `approval_task` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `node_id` bigint unsigned NOT NULL COMMENT '节点ID',
  `node_round` bigint NOT NULL COMMENT '节点轮次(退回重审递增,软删置-1)',
  `instance_id` bigint unsigned NOT NULL COMMENT '实例ID',
  `approver_id` bigint unsigned NOT NULL COMMENT '审批人ID',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务状态(PENDING/APPROVING/APPROVED/UNAPPROVED/REVOKED)',
  `type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '任务类型(CC抄送/SN加签/BK退回/NL常规)',
  `action` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批动作(APPROVE/REJECT/SIGN/BACK/REVOKE)',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_task_instance_node` (`node_id`,`instance_id`),
  KEY `idx_task_approver` (`approver_id`),
  KEY `idx_approval_task_created_at` (`created_at`),
  KEY `idx_approval_task_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=56 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='审批任务(待办)';

DROP TABLE IF EXISTS `casbin_rule`;

CREATE TABLE `casbin_rule` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `ptype` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `v0` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `v1` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `v2` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `v3` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `v4` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `v5` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_casbin_rule` (`ptype`,`v0`,`v1`,`v2`,`v3`,`v4`,`v5`)
