DROP TABLE IF EXISTS `cloud_file`;

CREATE TABLE `cloud_file` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `parent_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '父文件夹ID(0=根)',
  `name` varchar(255) NOT NULL COMMENT '文件/文件夹名',
  `is_dir` tinyint NOT NULL DEFAULT '0' COMMENT '0=文件 1=文件夹',
  `object_key` varchar(500) DEFAULT '' COMMENT 'OSS存储路径',
  `url` varchar(1000) DEFAULT '' COMMENT '访问URL',
  `size` bigint NOT NULL DEFAULT '0' COMMENT '文件大小(字节)',
  `content_type` varchar(100) DEFAULT '' COMMENT 'MIME类型',
  `scope` varchar(20) NOT NULL DEFAULT 'personal' COMMENT '权限(personal/dept/public)',
  `owner_id` bigint unsigned DEFAULT NULL COMMENT '归属人(personal时用)',
  `dept_id` bigint unsigned DEFAULT NULL COMMENT '归属部门(dept时用)',
  `creator_id` bigint unsigned NOT NULL COMMENT '上传/创建人',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1正常 0回收站',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_cloud_parent` (`parent_id`),
  KEY `idx_cloud_scope` (`scope`),
  KEY `idx_cloud_owner` (`owner_id`),
  KEY `idx_cloud_dept` (`dept_id`),
  KEY `idx_cloud_status` (`status`),
  KEY `idx_cloud_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='企业网盘文件';

