DROP TABLE IF EXISTS `cms_article`;

CREATE TABLE `cms_article` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL别名',
  `summary` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '摘要',
  `content` longtext COLLATE utf8mb4_unicode_ci COMMENT '正文',
  `cover_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封面图URL',
  `category_id` bigint unsigned DEFAULT NULL COMMENT '分类ID',
  `author_id` bigint unsigned DEFAULT NULL COMMENT '作者用户ID',
  `author_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '作者昵称(快照)',
  `status` tinyint DEFAULT '0' COMMENT '0草稿 1已发布',
  `is_top` tinyint DEFAULT '0' COMMENT '0否 1置顶',
  `is_hot` tinyint DEFAULT '0' COMMENT '0否 1热门',
  `view_count` bigint DEFAULT '0' COMMENT '浏览量',
  `sort` bigint DEFAULT '0' COMMENT '排序',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_cms_article_slug` (`slug`),
  KEY `idx_cms_article_category_id` (`category_id`),
  KEY `idx_cms_article_author_id` (`author_id`),
  KEY `idx_cms_article_status` (`status`),
  KEY `idx_cms_article_created_at` (`created_at`),
  KEY `idx_cms_article_deleted_at` (`deleted_at`),
  CONSTRAINT `fk_cms_article_category` FOREIGN KEY (`category_id`) REFERENCES `cms_category` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='文章';

INSERT INTO `cms_article` (`id`, `title`, `slug`, `summary`, `content`, `cover_url`, `category_id`, `author_id`, `author_name`, `status`, `is_top`, `is_hot`, `view_count`, `sort`, `created_at`, `updated_at`, `deleted_at`) VALUES (1, '行简一体化管理平台正式上新：软件免费，1000 元服务费即可上线', 'platform-launch', '整套企业管理软件免费提供给企业使用，只收一次性 1000 元部署服务费。CRM、审批流、进销存、财务、HRM、官网 CMS 全套模块，源码级部署到客户自己的阿里云。', '# 行简一体化管理平台正式上新\n\n我们把整套企业管理软件**免费**开放给企业使用：不限用户数、不限模块，源码级部署到客户自己的阿里云账号下，数据完全归客户所有。\n\n## 为什么免费\n\n软件已经是成熟产品，每多服务一家企业的边际成本很低。我们只收 **1000 元一次性部署服务费**（含部署、数据初始化、使用培训），后续如需定制功能按 **1000 元/人天**计费（价格可谈）。\n\n## 平台包含什么\n\n| 模块 | 内容 |\n| --- | --- |\n| CRM 客户管理 | 线索、公海、客户、联系人、跟进记录、商机、合同 |\n| 审批流 | 可视化流程设计器，条件分支、会签/或签/依次审批 |\n| 进销存 | 采购、销售、库存、仓库、供应商 |\n| 财务 | 账户、凭证、发票 |\n| HRM | 部门、员工、考勤、薪酬 |\n| 官网 CMS | 文章、分类、页面，数据实时同步企业官网 |\n\n![平台工作台](https://cdn.devlovecode.com/product/42736e7a60685ef01a9fb47189901f4d.png)\n\n## 客户需要准备什么\n\n- 2C4G 云服务器 ECS 一台\n- 2C2G MySQL RDS 实例一个\n- OSS 对象存储 + CDN 加速\n- 域名一个（没有可协助申请与备案）\n- 阿里云账号保留 1000 元余额即可覆盖基础开销\n\n> 以上资源我们都可以协助申请、配置与调优，客户不需要任何运维经验。\n\n**1000 元服务费 + 阿里云基础资源，就能拥有一套属于自己的企业管理系统。**', 'https://cdn.devlovecode.com/product/42736e7a60685ef01a9fb47189901f4d.png', 1, 1, '行简团队', 1, 1, 1, 226, 1, '2026-08-04 17:58:27.959', '2026-08-05 16:47:38.132', NULL), (2, 'CRM 客户管理：从线索公海到成交的全生命周期', 'crm-lifecycle', '线索、公海、客户、联系人、跟进记录、商机、合同一体化管理。支持自定义字段、客户公海自动回收、线索一键转客户，让每一条商机都有迹可循。', '# CRM 客户管理：从线索公海到成交的全生命周期\n\n销售团队最头疼的三件事：线索没人跟、客户撞单、离职带走客户。行简 CRM 用一套完整机制解决它们。\n\n## 线索 → 客户，一条流水线\n\n1. **线索录入**：市场活动、官网表单、手工录入，全部先进线索池\n2. **线索公海**：超时未跟进自动掉入公海，其他销售可领取，杜绝浪费\n3. **一键转化**：确认意向后线索一键转客户，历史跟进记录自动随迁\n4. **客户跟进**：联系人、跟进记录、下次跟进计划全程留痕\n\n## 客户公海，盘活存量资源\n\n- 可配置**回收规则**：N 天未跟进自动回收进公海\n- 可配置**领取规则**：每人持有上限、每日领取上限\n- 公海池支持**隐藏字段**，保护敏感信息不被围观\n\n![客户管理列表](https://cdn.devlovecode.com/product/9cedba50243387cff6152a732ab233d1.png)\n\n## 商机与合同\n\n- 商机按**阶段**推进（初步接触 → 需求确认 → 报价 → 赢单/输单），阶段可自定义\n- 合同关联商品与价格，支持**分期回款计划**与回款记录\n- 全部支持审批流：报价审批、合同审批、回款确认，一个平台走完\n\n## 自定义字段\n\n标准字段不够用？字段设计器里点几下就能给客户表单加字段，文本、数字、日期、下拉、人员、部门等 26 种类型，无需改代码、无需发版。', 'https://cdn.devlovecode.com/product/9cedba50243387cff6152a732ab233d1.png', 2, 1, '行简团队', 1, 0, 1, 118, 2, '2026-08-04 17:58:28.095', '2026-08-05 16:47:38.289', NULL), (3, '自定义字段设计器：零代码扩展业务表单', 'custom-field-designer', '三栏式可视化字段设计器：左侧 26 种字段类型、中间表单实时预览、右侧属性编辑。客户、商机、合同、商品、跟进记录全部支持自定义扩展，业务人员零代码上手。', '# 自定义字段设计器：零代码扩展业务表单\n\n每家企业的业务表单都不一样。传统做法是提需求、排期、改代码、发版——一个字段等两周。行简的自定义字段设计器把这件事缩短到**一分钟**。\n\n## 三栏式所见即所得\n\n- **左栏：字段类型面板**——26 种字段类型分常用/人员组织/高级三组，文本、多行文本、数字、金额、日期、单选、多选、下拉、人员、部门、地址、网址、电话、邮箱……点一下即添加\n- **中栏：表单实时预览**——真实控件渲染，点选卡片即可编辑，支持上移/下移/删除\n- **右栏：属性编辑**——字段名、占位提示、字段说明、必填、可见、可编辑、移动端显示、半行/整行宽度、选项值编辑\n\n![自定义字段设计器](https://cdn.devlovecode.com/product/6a4f63050a76fbbfac354b9e975725ba.png)\n\n## 支持的业务对象\n\n客户、商机、合同、商品、跟进记录——CRM 核心表单全部开放自定义。\n\n## 选项类字段怎么配\n\n单选/多选/下拉类字段，在右侧属性面板按 `值|标签` 每行一条录入即可，比如：\n\n```\nA|重点客户\nB|普通客户\nC|观察客户\n```\n\n保存后立即在所有端（Web 后台、移动端）生效，不需要任何发版。', 'https://cdn.devlovecode.com/product/6a4f63050a76fbbfac354b9e975725ba.png', 2, 1, '行简团队', 1, 0, 0, 113, 3, '2026-08-04 17:58:28.399', '2026-08-05 16:47:38.358', NULL), (4, '可视化审批流设计器：拖拽搭建企业审批流程', 'approval-flow-designer', '基于可视化画布的审批流设计器：在连线上点 + 插入审批节点或条件分支，右侧配置审批人（成员/角色/上级/部门负责人），支持会签、或签、依次审批与空审批人兜底策略。', '# 可视化审批流设计器：拖拽搭建企业审批流程\n\n请假、报销、合同、报价……每家企业都有几十条审批流程。行简的审批流设计器让管理员在画布上**点几下**就能搭好一条流程。\n\n## 画布式编辑\n\n- 流程以「开始 → 结束」为骨架，在**连线上点 + 号**即可插入节点\n- 支持两类节点：**审批节点**与**条件分支节点**（按表单字段值走不同分支）\n- 删除节点自动重连前后节点，不怕改乱\n\n![审批流程设计器](https://cdn.devlovecode.com/product/327cf85332b04b1ad20a277208135a92.png)\n\n## 灵活的审批人配置\n\n| 审批人类型 | 适用场景 |\n| --- | --- |\n| 指定成员 | 固定由某人审批 |\n| 指定角色 | 如"财务专员"角色中任一人 |\n| 直属上级 | 按汇报关系自动找人 |\n| 多级上级 | 层层上报到第 N 级 |\n| 部门负责人 | 提交人所在部门的负责人 |\n| 多级部门负责人 | 跨层级部门负责人逐级审批 |\n\n## 多人审批模式与兜底策略\n\n- **会签**：所有人同意才算通过\n- **或签**：任一人同意即通过\n- **依次审批**：按顺序逐个审批\n- 审批人为空时可配置**自动通过**、**转交指定人**或**转交管理员**，流程永远不卡死\n\n条件分支按表单字段配置规则（等于/大于/包含等，支持 AND/OR 组合），比如"金额 ≥ 10000 走总经理审批，否则走部门经理审批"。', 'https://cdn.devlovecode.com/product/327cf85332b04b1ad20a277208135a92.png', 2, 1, '行简团队', 1, 0, 0, 112, 4, '2026-08-04 17:58:28.544', '2026-08-05 16:47:38.419', NULL), (5, '商品与内容管理：Markdown 富文本 + OSS/CDN 图片加速', 'product-cms-markdown', '商品支持主图上传（OSS 存储 + CDN 全球加速）与 Markdown 富文本详情；CMS 文章同样使用 Markdown 编辑器，内容实时同步到企业官网并服务端渲染，SEO 友好。', '# 商品与内容管理：Markdown 富文本 + OSS/CDN 图片加速\n\n商品和文章内容，是企业对外的门面。行简在这件事上做了三个关键选择。\n\n## 1. Markdown 作为内容格式\n\n商品详情和 CMS 文章统一使用 **Markdown 编辑器**（带实时预览）。标题、表格、图片、代码块、引用都能写，格式干净、迁移方便，不会被富文本编辑器生成的冗余 HTML 污染。\n\n官网前端用 react-markdown 服务端渲染成 HTML，配合 GFM 表格样式，**SEO 友好、加载飞快**。\n\n![商品编辑（Markdown + 图片上传）](https://cdn.devlovecode.com/product/a348946d68f5d88ee70dd4ef8f6a0023.png)\n\n## 2. 图片统一走 OSS + CDN\n\n后台任何图片上传（商品主图、文章封面、站点 Logo）都会存入阿里云 OSS，并通过 CDN 域名访问：\n\n- 源站私有，**回源走 CDN**，OSS 不直接暴露\n- 全国节点加速，官网图片秒开\n- 免费通配符 HTTPS 证书，全链路加密\n\n## 3. 业务数据即官网内容\n\n商品、文章在后台维护后，企业官网**自动同步展示**，无需单独维护两套内容：\n\n![商品管理列表](https://cdn.devlovecode.com/product/242ff4c039cf05ad405196efcb5f8bdd.png)\n\n后台改一行字，官网 5 分钟内更新（ISR 增量静态再生成）。内容团队只管写，技术的事平台全包了。', 'https://cdn.devlovecode.com/product/a348946d68f5d88ee70dd4ef8f6a0023.png', 2, 1, '行简团队', 1, 0, 0, 89, 5, '2026-08-04 17:58:28.677', '2026-08-05 16:47:38.487', NULL), (6, '1000 元，买不了吃亏买不了上当：一套完整企业管理系统的底气', '500-yuan-worth-it', '花 1000 元部署费，就能拥有涵盖 CRM、审批流、进销存、财务、HRM、官网 CMS 的全套企业管理软件。源码进自家服务器，数据完全归你。算总账，这笔买卖怎么算都不亏。', '# 1000 元，买不了吃亏买不了上当：一套完整企业管理系统的底气\n\n"**1000 元，买不了吃亏买不了上当。**"这句话我们敢喊出来，是有底气的。\n\n## 这套系统，到底值多少钱？\n\n先算一笔账。市面上一套涵盖 **CRM + 审批流 + 进销存 + 财务 + HRM + 官网 CMS** 的企业管理软件，动辄：\n\n- **SaaS 订阅**：按用户/年收费，10 人团队一年大几千到几万；\n- **私有化部署**：一次性授权费普遍在 **5 万到 50 万**之间，还要再付实施费；\n- **功能不全**：很多号称"全模块"的产品，进销存和 CRM 还是两套割裂的系统。\n\n而行简把**整套源码**交付给客户，**软件免费**，只收 **1000 元一次性部署服务费**。省下的不只是钱，更是一次性的安心——**系统部署在你自己账号下的服务器里，数据完全归你，永远不担心供应商跑路或涨价**。\n\n## 1000 元具体买到什么\n\n| 你得到 | 价值 |\n| --- | --- |\n| 全套源码级部署 | 免费，市场价 5 万+ |\n| CRM 客户全生命周期 | 线索、公海、商机、合同、回款一体化 |\n| 可视化审批流设计器 | 拖拽搭流程，零代码 |\n| 进销存 + 财务 + HRM | 一平台覆盖采购、库存、人事、考勤 |\n| 官网 CMS 自动同步 | 内容后台维护，官网实时更新 |\n| 部署、数据初始化、使用培训 | 全程协助，无需运维经验 |\n\n合计仅 **1000 元**，一次付费、长期使用。\n\n## 这买卖怎么算都不亏\n\n- 软件**免费**——我们靠定制服务（1000 元/人天）和口碑活，前期宁可少赚也要先把产品铺出去；\n- 资源是自己的——阿里云服务器、数据库、OSS 都在你名下，随时可以带走、扩容；\n- 不满意可以不用——部署在自己环境，没有任何锁死和隐藏费用。\n\n**1000 元，买不了吃亏，买不了上当，买到的是一套真正属于你自己的企业管理系统。** 一次部署，长期受益。\n\n> 部署只需 2C4G 云服务器一台 + MySQL + OSS + 域名，阿里云账号留 1000 元余额即可覆盖基础开销，资源与备案我们全程协助。\n', 'https://cdn.devlovecode.com/product/42736e7a60685ef01a9fb47189901f4d.png', 1, 1, '行简团队', 1, 0, 1, 51, 1, '2026-08-07 09:48:48.969', '2026-08-07 09:48:48.969', '2026-08-21 23:00:00.679'), (7, '一年 SaaS 订阅费 vs 一次性 1000 元：这笔账你会算吗？', 'saas-vs-500', '传统 SaaS 按年订阅、按人收费，几年下来是一笔不小的持续支出。行简一次 1000 元部署费拿下整套系统，源码在自己手里，越用越省。算清楚这笔账，你就知道该选谁。', '# 一年 SaaS 订阅费 vs 一次性 1000 元：这笔账你会算吗？\n\n很多老板看到"免费软件只收 1000 元"，第一反应是"便宜没好货"。我们先把账算清楚。\n\n## 传统 SaaS 的隐藏账单\n\n以一套主流企业管理 SaaS 为例，按**每用户每年**收费：\n\n| 团队规模 | 单价 | 一年费用 | 三年费用 |\n| --- | --- | --- | --- |\n| 10 人 | 1000 元/人/年 | 5,000 元 | 15,000 元 |\n| 20 人 | 1000 元/人/年 | 10,000 元 | 30,000 元 |\n| 50 人 | 400 元/人/年 | 20,000 元 | 60,000 元 |\n\n这是**持续支出**——只要还用着 SaaS，这笔钱每年都得掏。而且用户数一涨，账单跟着涨；功能模块想多加，还要再按模块加钱。\n\n## 行简：一次付费，长期使用\n\n| 对比项 | 传统 SaaS | 行简 |\n| --- | --- | --- |\n| 费用模式 | 按年/按人头持续付费 | **一次性 1000 元部署费** |\n| 用户数上限 | 受套餐限制 | **不限用户数** |\n| 数据归属 | 在供应商云端 | **完全在自己服务器** |\n| 源码 | 拿不到 | **源码级交付** |\n| 后续支出 | 年年交 | 0（仅按需定制 1000 元/人天） |\n\n只看第一年，10 人团队行简就比 SaaS 省下 **4,1000 元**；用的越久、人越多，省得越多。**3 年省 1.5 万，5 年省 2.5 万**，还不用担心续费涨价。\n\n## 便宜，是因为我们想清楚了\n\n软件是成熟产品，边际成本低，所以我们敢免费。真正收钱的是**定制服务**——客户按自己业务改需求，我们按 1000 元/人天帮忙实现。**成交靠的是产品和口碑，不是靠软件费。**\n\n所以，**不要拿"1000 元"和"几万块的 SaaS"比单价，要比就比总账**——哪个让你越用越省、数据越用越安心，答案很清楚。\n\n> 行简，1000 元买不了吃亏买不了上当，买到的是一套真正省心省钱的完整管理系统。\n', 'https://cdn.devlovecode.com/product/9cedba50243387cff6152a732ab233d1.png', 1, 1, '行简团队', 1, 0, 1, 98, 2, '2026-08-07 09:48:56.863', '2026-08-07 09:48:56.863', NULL), (8, '数据在自己手里，才谈得上安全：为什么要选源码部署', 'data-ownership', '客户资料、合同金额、员工薪酬——这些核心数据放在别人云上，你睡得着吗？行简把全套源码部署到你的阿里云，数据 100% 归你所有，没有供应商锁定，没有涨价绑架。1000 元买的是这份踏实。', '# 数据在自己手里，才谈得上安全：为什么要选源码部署\n\n做企业的都明白：**客户资料、合同金额、采购价格、员工薪酬，任何一样泄露出去，都是大麻烦。**\n\n传统 SaaS 模式下，这些最核心的业务数据都存在供应商的云端，你只拥有"使用权"：\n\n- 供应商倒了，数据怎么办？\n- 供应商涨价、改条款，你只能接受？\n- 想换系统、导数据，导出得痛快吗？\n\n## 行简：源码部署，数据 100% 归你\n\n我们做的是**私有化交付**——整套系统部署在**客户自己的阿里云账号**下：\n\n- **数据库、OSS 存储都在你名下**，别人碰不到；\n- **数据完全归客户所有**，随时导出、随时带走；\n- **没有供应商锁定**，不喜欢随时可以弃用；\n- **没有续费绑架**，一次 1000 元部署费，之后不再按年收钱。\n\n## 部署在自己环境，反而更自由\n\n很多人担心"私有化是不是很麻烦"。其实行简全程协助，客户几乎不需要运维经验：\n\n| 客户要做的 | 行简协助 |\n| --- | --- |\n| 一台 2C4G 云服务器 | 协助申请、配置、调优 |\n| MySQL 数据库 | 建库建表、数据初始化 |\n| OSS + CDN | 配置存储与加速 |\n| 域名/备案 | 协助申请与备案 |\n\n部署完，系统、数据、代码全在你自己的资源上。**这种安全感，是订阅制 SaaS 给不了的。**\n\n## 1000 元，买的是一份踏实\n\n很多人说 SaaS 方便、省心。但把核心数据托管在别人手里，终究是"心里没底"。行简用 **1000 元**帮你把系统搬回家——**数据在你手里，才谈得上安全，才谈得上真正属于你。**\n\n> 行简：1000 元部署费，一套完整系统，源码数据全归你。买不了吃亏，买不了上当。\n', 'https://cdn.devlovecode.com/product/6a4f63050a76fbbfac354b9e975725ba.png', 1, 1, '行简团队', 1, 0, 0, 94, 3, '2026-08-07 09:49:04.152', '2026-08-07 09:49:04.152', NULL), (9, '为什么我们敢说"1000 元买到完整管理系统"？今天把底牌亮给你', 'why-500-card', '功能一个不少、产品成熟可用、靠定制服务盈利、不满意随时能走——这就是我们敢把整套系统只卖 1000 元部署费的四个底牌。风险归零，买不了吃亏买不了上当。', '# 为什么我们敢说"1000 元买到完整管理系统"？今天把底牌亮给你\n\n常有人问："这么便宜，是不是功能缺胳膊少腿？"今天我们把底牌全部亮出来，让您自己判断。\n\n## 底牌一：功能一个不少\n\n行简不是"轻量版"，而是一套**五脏俱全**的企业管理系统：\n\n| 模块 | 覆盖能力 |\n| --- | --- |\n| CRM | 线索、公海、客户、联系人、跟进、商机、合同、回款 |\n| 审批流 | 可视化设计器、条件分支、会签/或签/依次审批 |\n| 进销存 | 采购、销售、库存、仓库、供应商 |\n| 财务 | 账户、凭证、发票 |\n| HRM | 部门、员工、考勤、薪酬 |\n| CMS | 官网文章、分类、页面，业务数据实时同步 |\n\n**大厂的 SaaS 有的，这里都有；私有化部署该有的数据主权，这里也有。**\n\n## 底牌二：成熟产品，不是实验品\n\n市面上几万块的系统我们做了好几年、叠了很多客户需求才打磨到这个程度。**软件本身已成熟，每多服务一家企业，边际成本很低**——所以我们敢免费，只收 1000 元部署费。\n\n## 底牌三：我们的盈利点在"定制"\n\n软件免费，那靠什么活？靠**定制服务**。客户业务独特、标准功能满足不了时，我们按 **1000 元/人天**帮您实现（价格可谈）。**先让产品帮您省钱，您的认可就是我们最大的招牌。**\n\n## 底牌四：不满意随时走\n\n系统部署在您自己的服务器上，**没有锁死、没有隐藏费用**。用着不合适，随时可以停用，数据还在您手里。**风险归零，才配叫"买不了吃亏买不了上当"。**\n\n## 1000 元，您买的是\n\n- 一套完整的、可商用的企业管理系统；\n- 一段稳稳的、数据归己的安全性；\n- 一份长期的、越用越省的性价比。\n\n**这就是我们的底气。1000 元，买不了吃亏，买不了上当——您拿走一套系统，我们就多一个口碑。**\n', 'https://cdn.devlovecode.com/product/327cf85332b04b1ad20a277208135a92.png', 1, 1, '行简团队', 1, 0, 1, 89, 4, '2026-08-07 09:49:13.503', '2026-08-07 09:49:13.503', NULL), (10, '1000 元能买到的完整管理栈：六个模块一网打尽', 'six-modules-500', 'CRM、审批流、进销存、财务、HRM、官网 CMS——六大模块单独订阅一年轻松上万，行简 1000 元一次性全拿下，还不限用户数、源码归你。买得明明白白。', '# 1000 元能买到的完整管理栈：六个模块一网打尽\n\n很多老板问：1000 元到底能买到什么"铁打的"功能？今天用一张图说清楚——行简把企业最常用的**六大模块**装进一套系统里。\n\n## 1. CRM：把客户管得明明白白\n\n线索录入、公海回收、一键转客户，商机按阶段推进，合同关联回款计划。**从"认识客户"到"收到款"，全程留痕。**\n\n## 2. 审批流：流程自己搭\n\n可视化画布上点几下，就能拖出一条请假、报销、合同、报价的审批流。支持会签、或签、依次审批，还能按条件走不同分支。**再也不用求着 IT 改流程。**\n\n## 3. 进销存：货从哪来、到哪去\n\n采购订单、销售订单、库存、仓库、供应商统一管理。**每一笔进出库都有流水，库存告警不担心断货。**\n\n## 4. 财务：账目清清楚楚\n\n账户、凭证、发票统一记账，配合回款计划与回款记录，**钱去哪了、还有多少没收回来，一眼看清。**\n\n## 5. HRM：人事考勤一把抓\n\n部门、员工、职位、考勤打卡、月度汇总、薪酬单，**人事行政的工作量直接减半。**\n\n## 6. 官网 CMS：内容自动上官网\n\nMarkdown 写文章、传产品，**后台一更新，企业官网 5 分钟内同步**，SEO 友好、加载快。\n\n## 六大模块，一套系统，1000 元\n\n| 模块 | 单独买市场价 |\n| --- | --- |\n| CRM | 数千~数万/年 |\n| 审批流 | 数千/年 |\n| 进销存 | 数千~数万/年 |\n| 财务 | 数千/年 |\n| HRM | 数千/年 |\n| 官网 CMS | 数千/年 |\n\n单独订阅加起来一年轻松上万，而行简 **1000 元全部拿下**，还是一次性、不限用户数、源码归你。\n\n**六个模块、一个平台、一次付款。1000 元，买不了吃亏买不了上当，就是买得明明白白。**\n', 'https://cdn.devlovecode.com/product/a348946d68f5d88ee70dd4ef8f6a0023.png', 2, 1, '行简团队', 1, 0, 0, 69, 5, '2026-08-07 09:49:21.267', '2026-08-07 09:49:21.267', NULL), (11, '从 0 到上线：1000 元部署一套企业管理系统，只需 7 步', 'deploy-7-steps', '确认需求→准备云资源→付 1000 元→源码部署→数据初始化→使用培训→长期陪伴，7 步走完，一套完整管理系统就上线了。全程协助，部署加初始化加培训全含在 1000 元里。', '# 从 0 到上线：1000 元部署一套企业管理系统，只需 7 步\n\n担心"便宜没好货、部署很麻烦"？其实从成交到系统跑起来，只要 7 步，全程我们陪跑。\n\n## 第 1 步：确认需求\n\n告诉我们团队规模、行业、常用模块，我们给出规划建议。**不额外收费，只是聊聊。**\n\n## 第 2 步：准备云资源\n\n阿里云账号准备：一台 **2C4G 云服务器 ECS** + **2C2G MySQL RDS** + **OSS 对象存储** + 一个域名。没经验？**我们全程协助申请、配置与备案。**\n\n## 第 3 步：支付 1000 元部署费\n\n一次性服务费，含部署、数据初始化、使用培训。**没有隐藏费用，没有后续年费。**\n\n## 第 4 步：源码部署上线\n\n我们把整套系统源码部署到**您自己账号的服务器**上，配置数据库、存储、域名、HTTPS。**数据从第一天起就在您手里。**\n\n## 第 5 步：数据初始化\n\n按您的组织架构，初始化部门、员工账号、角色权限，配置好审批流等基础设置。**开箱即可用，而不是空壳。**\n\n## 第 6 步：使用培训\n\n远程演示核心功能，教管理员和员工上手——CRM 怎么跟进、审批流怎么搭、考勤怎么打。**有问题随叫随到。**\n\n## 第 7 步：长期陪伴\n\n部署完不是结束。日常问题、小优化、按需定制（1000 元/人天）随时响应。**您只管用，技术的事交给我们。**\n\n## 全程 1000 元，就酱\n\n| 步骤 | 谁来做 | 费用 |\n| --- | --- | --- |\n| 需求确认 | 行简 | 免费 |\n| 云资源准备 | 客户 + 行简协助 | 阿里云按量 |\n| 部署服务费 | — | **1000 元** |\n| 源码部署 | 行简 | 已含 |\n| 数据初始化 | 行简 | 已含 |\n| 使用培训 | 行简 | 已含 |\n| 长期运维陪伴 | 行简 | 按需 |\n\n**7 步走完，一套属于自己的完整管理系统就在眼前。1000 元，买不了吃亏，买不了上当——这是把企业搬上数字化的最低门槛。**\n', 'https://cdn.devlovecode.com/product/242ff4c039cf05ad405196efcb5f8bdd.png', 1, 1, '行简团队', 1, 0, 0, 63, 6, '2026-08-07 09:49:29.280', '2026-08-07 09:49:29.280', NULL), (12, '让 AI 直接操作你的业务数据：行简的 MCP 协议落地实践', 'mcp-practice', '我们在企业管理系统里实现了 MCP(Model Context Protocol)端点，让 Claude、Cursor、Codex 等 AI 工具能直接读写 CRM 客户、创建合同、查询库存。本文分享实现思路和配置方法。', '# 让 AI 直接操作你的业务数据：行简的 MCP 协议落地实践\n\n如果你用 Cursor、Claude Code 或 Codex 写代码，你一定知道 MCP（Model Context Protocol）——它让 AI 能连接外部工具。但你是否想过：**让 AI 直接连到你的企业管理系统，帮你查客户、建合同、看库存？**\n\n我们在行简里做了这件事。\n\n## MCP 是什么，为什么重要\n\nMCP 是 Anthropic（Claude 的开发商）推出的开放协议，核心很简单：\n\n> **AI 工具 ←→ MCP Server ←→ 你的业务系统**\n\n之前 AI 只能帮你写代码、写文档。有了 MCP，AI 可以**直接操作业务数据**——"帮我查一下张三的合同回款进度""把这条线索转成客户""这周哪些客户该跟进了"。\n\n这不是 demo，是生产可用。\n\n## 我们怎么实现的\n\n行简后端用 Go 写，我们在 Gin 路由上挂了一个 `/mcp` 端点：\n\n```\nPOST https://devlovecode.com/mcp\nAuthorization: Bearer qzt_xxxxxxxxxxxxxxxx\n```\n\n### 认证：API Key\n\nMCP 端点用 **API Key 认证**（`qzt_` 前缀），不走 JWT。用户在后台「个人中心 → API Key」一键生成，key 只存 SHA256 哈希，明文只展示一次。\n\n### 数据权限：和你登录网页一样\n\n关键设计：MCP 请求和网页请求走**同一套数据权限**。你用 zhangsan 的 API Key，AI 查到的客户数据和 zhangsan 登录网页看到的一模一样——**三层权限校验全生效**：\n\n1. **前端路由守卫**——没权限的模块不暴露 MCP 工具\n2. **Casbin RBAC**——API 层拦截无权限的操作\n3. **data_scope 行级过滤**——销售只看自己的客户，经理看团队的\n\n这意味着你可以放心地给 AI 一个低权限的 Key，它不会越权。\n\n### 一键生成客户端配置\n\n用户创建 API Key 后，后台自动生成各客户端的配置：\n\n**Claude Code / Claude Desktop**（`.mcp.json`）：\n```json\n{\n  "mcpServers": {\n    "qzt-erp": {\n      "type": "http",\n      "url": "https://devlovecode.com/mcp",\n      "headers": { "Authorization": "Bearer qzt_xxx..." }\n    }\n  }\n}\n```\n\n**Codex CLI**（`~/.codex/config.toml`）：\n```toml\n[mcp_servers.qzt-erp]\ntransport = "http"\nurl = "https://devlovecode.com/mcp"\nauth_token = "qzt_xxx..."\n```\n\n**Cursor**、**VS Code (GitHub Copilot)** 同样支持，复制即用。\n\n## 实际效果\n\n配置好 MCP 后，在 Claude/Cursor 里直接对话：\n\n- *"帮我看看本周新增的客户"*\n- *"把 X 公司的商机阶段从「初步接触」推进到「方案报价」"*\n- *"这个月的回款汇总是多少？"*\n- *"帮我给跟进超 7 天的线索发个提醒"*\n\nAI 通过 MCP 调用后端接口，返回真实业务数据。**不需要你切到后台手动操作，也不需要写脚本。**\n\n## 为什么这很重要\n\n企业管理软件最大的痛点不是功能少，而是**操作繁琐**。老板想看个数据要找人导 Excel，销售想更新跟进要打开系统点半天。MCP + AI 改变了交互方式——**用自然语言操作业务系统**。\n\n我们可能是国内最早把 MCP 原生集成进企业管理平台的团队。这不是噱头，是生产环境跑通的。\n\n---\n\n> 想体验？访问 [在线体验](/p/demo) 页面，用 demo 账号登录后台，在「个人中心 → API Key」生成你的 Key，然后在 Claude/Cursor 里配置即可。', 'https://cdn.devlovecode.com/product/9cedba50243387cff6152a732ab233d1.png', 2, 1, '行简团队', 1, 0, 1, 170, 0, '2026-08-08 16:47:39.058', '2026-08-08 16:48:56.505', NULL), (13, '你的 CRM 知道客户付款了吗？聊聊企业软件的"数据孤岛"', 'data-silo', 'CRM 里记了客户信息，进销存里记了订单，财务里记了回款——但它们互相不知道对方的存在。这就是数据孤岛。一套系统全打通，才是企业管理该有的样子。', '# 你的 CRM 知道客户付款了吗？聊聊企业软件的"数据孤岛"\n\n问一个简单的问题：**你的 CRM 系统，能直接看到这个客户有没有付款吗？**\n\n大多数企业的答案是：不能。\n\n## 数据孤岛是怎么产生的\n\n一个典型的 30 人公司，软件栈长这样：\n\n| 用途 | 软件 |\n| --- | --- |\n| 客户管理 | 某 CRM SaaS |\n| 审批流程 | 钉钉/飞书 |\n| 进销存 | 某进销存 SaaS |\n| 财务记账 | 金蝶/用友 |\n| 人事考勤 | 钉钉考勤 |\n| 内部沟通 | 微信群 |\n\n每套系统都是独立的，数据不互通。于是出现了这些场景：\n\n- **销售**在 CRM 里跟进了 3 个月的客户签了合同，但**不知道财务有没有收到首付款**\n- **采购**下了采购单，但**仓库系统里看不到**，只能手动复制\n- **老板**想知道"这个月哪个客户回款最多"，得让**三个人分别从三个系统导 Excel 再拼**\n- **新员工**入职要开 **5 个系统账号**，记 5 套密码\n\n这就是数据孤岛。每个系统单看都没问题，合在一起就是灾难。\n\n## 数据孤岛的真正代价\n\n你以为代价是"效率低"？不，**真正的代价是你做不出正确的决策**。\n\n- 客户已付款但销售不知道，继续催款 → **客户体验差**\n- 库存已售罄但销售还在接单 → **违约风险**\n- 某产品销量很好但采购看不到数据 → **断货**\n- 老板等月报才知道问题，但问题已经发生了两周 → **决策滞后**\n\n**数据不通，本质上是让企业在蒙眼狂奔。**\n\n## 一套系统 vs 五套 SaaS\n\n行简的思路很简单：**把 CRM、审批、进销存、财务、HRM、OA 放进一个系统**。\n\n| 场景 | 5 套 SaaS 拼凑 | 行简一体化 |\n| --- | --- | --- |\n| 客户签了合同 | 手动复制到进销存建销售单 | 合同自动关联，一键生成 |\n| 客户付款了 | 财务记账，销售不知道 | 回款记录自动同步，销售实时看到 |\n| 请采购审批 | 审批系统批完，再手动去采购系统下单 | 审批通过直接触发采购流程 |\n| 新员工入职 | 开 5 个账号 | 开 1 个账号，按角色配权限 |\n| 老板看数据 | 三个人导 Excel 拼 | 打开工作台，实时看全盘 |\n\n**一个数据库，一套权限，一张工作台。** 这不是"功能多"，而是"数据通"。\n\n## 私有化部署：数据归你，不归 SaaS 厂商\n\n还有一个很多人忽略的问题：**用 SaaS，你的客户数据、合同金额、财务数据都在别人服务器上**。\n\nSaaS 厂商可以：\n- 看到你的全部业务数据\n- 涨价时你没有议价权（数据在人家手里）\n- 哪天倒闭了，你的数据可能拿不回来\n\n行简选择**私有化部署**：源码部署到你自己的服务器，数据完全归你。不满意可以随时迁走，没有任何锁定。\n\n## 1000 元，让数据真正流通起来\n\n行简**软件免费**，只收 **1000 元一次性部署服务费**。不限用户数，不限模块。\n\n你得到的是：\n- 13 个业务模块全部打通的一体化系统\n- 部署在自己服务器上的私有化数据\n- 可按需定制的源码级交付\n\n**当你的 CRM 能直接看到回款、你的审批能直接驱动采购、你的老板打开一个页面就能看到全盘——这才是企业管理该有的样子。**\n\n---\n\n> 告别数据孤岛，从一个系统开始。[在线体验 →](/p/demo)', 'https://cdn.devlovecode.com/product/42736e7a60685ef01a9fb47189901f4d.png', 1, 1, '行简团队', 1, 0, 1, 181, 0, '2026-08-08 16:48:07.188', '2026-08-08 16:48:56.667', NULL), (14, '123 张表、13 个模块、411 个 API：行简的完整技术架构', 'tech-stack', 'Go 1.25 + Gin + GORM + React 19 + TypeScript + Next.js 15。123 张表、13 个模块、411 个 API、三层权限体系、MCP 原生支持。一套完整的、生产级的企业管理平台技术架构。', '# 123 张表、13 个模块、411 个 API：行简的完整技术架构\n\n如果你是一个独立开发者或 ISV，正在给客户交付企业管理系统，你可能面临一个选择：\n\n1. **从零开发**——6 个月起步，踩无数坑\n2. **基于开源项目二开**——但大部分开源 ERP 要么太重（Odoo），要么太旧（技术栈过时），要么不完整（只有 CRM 没有财务）\n\n行简是第三个选择：**一套现代化的、完整的、可直接交付的企业管理平台。**\n\n## 技术栈\n\n| 层 | 技术选型 | 为什么选 |\n| --- | --- | --- |\n| **后端** | Go 1.25 + Gin + GORM | 编译型、高并发、单二进制部署 |\n| **权限** | Casbin RBAC | 成熟的策略引擎，支持 API 级权限 |\n| **缓存** | Redis | 会话、限流、字典缓存 |\n| **管理后台** | React 19 + TypeScript + Ant Design Pro | 企业级 UI 组件库，CRUD 页面开发极快 |\n| **官网** | Next.js 15 + Tailwind CSS | SSR/ISR，SEO 友好 |\n| **移动端** | React 19 + Ant Design Mobile | H5 适配 |\n| **数据库** | MySQL (utf8mb4) | 生产成熟 |\n\n**单仓多项目**：后端、管理后台、官网、移动端在一个 git 仓库里，统一管理，没有微服务的运维复杂度。\n\n## 13 个业务模块\n\n每个模块都是**生产可用**的完整实现（不是 PPT）：\n\n| 模块 | 路由数 | 核心能力 |\n| --- | --- | --- |\n| CRM | 125 | 线索→客户→商机→合同→回款 全生命周期 |\n| 系统 | 70 | 用户/角色/菜单/字典/API/Casbin 权限 |\n| HRM | 49 | 部门/员工/考勤/薪酬/绩效/招聘 |\n| PSI | 47 | 采购/销售/库存/退货/资产/报表 |\n| 企业应用 | 25 | 消息/公告/定时任务/日志 |\n| CMS | 29 | 文章/分类/单页/标签 |\n| OA | 17 | 报销/借款/差旅 |\n| 审批 | 13 | 可视化流程设计器，条件分支/会签/或签 |\n| 财务 | 13 | 会计科目/凭证/应收应付/发票/报表 |\n| 项目 | 10 | 项目/任务/状态流转 |\n| 仪表盘 | 23 | 核心指标/趋势图/漏斗/分布图 |\n| AI | 7 | AI 助手/MCP Server |\n| API | 23 | BI 报表聚合 |\n\n## 三层权限体系\n\n这是最值得说的部分。不是简单的"有没有权限"，而是**纵深防御**：\n\n```\n请求 → ① 前端路由守卫（菜单无权限 → 404 页面）\n     → ② Casbin RBAC（API 无权限 → 403）\n     → ③ data_scope 行级过滤（按 owner_id / dept_id 过滤数据行）\n```\n\n**data_scope 支持 4 种范围**：\n- `1` 全部数据（超管）\n- `3` 本部门数据\n- `4` 本部门及子部门（主管）\n- `5` 仅本人数据\n\n这套权限是**在数据层强制执行的**，不是前端隐藏按钮那种假权限。我们在生产环境用 6 个角色 × 56 个测试点验证过，无越权。\n\n## MCP 原生支持\n\n后端内置 MCP Server（Streamable HTTP），AI 工具（Claude / Cursor / Codex）可以直接连接：\n\n- 端点：`POST /mcp`\n- 认证：API Key（`qzt_` 前缀）\n- 权限：MCP 请求和网页请求走**同一套 data_scope + RBAC**\n\n这是目前国产 ERP 里极少数原生集成 MCP 的。\n\n## 部署方式\n\n**单二进制 + 静态文件**，极简部署：\n\n```bash\n# 后端\nGOOS=linux GOARCH=amd64 go build -o qzt-server ./cmd/server\n\n# 前端\npnpm build  # → dist/ 纯静态\n\n# 部署\nsystemctl start qzt-server   # 后端\nnginx serve dist/             # 前端\n```\n\n生产环境只需 **2C4G 服务器 + MySQL + OSS**，总成本极低。\n\n## 对 ISV / 开发者意味着什么\n\n如果你在给客户交付企业管理系统：\n\n1. **不用从零开始**——123 张表、411 个 API 全部现成\n2. **可以按需裁剪**——不需要的模块删掉不影响其他模块\n3. **可以深度定制**——源码级交付，改什么都行\n4. **1000 元就能交付**——部署成本极低，客户容易接受\n\n**这不是一个 demo，是一个跑在生产环境、经过权限测试、有真实客户的系统。**\n\n---\n\n> 技术问题交流 / ISV 合作：shichenyang@devlovecode.com / 15139960649\n> \n> [在线体验 →](/p/demo)', 'https://cdn.devlovecode.com/product/9cedba50243387cff6152a732ab233d1.png', 2, 1, '行简团队', 1, 0, 1, 186, 0, '2026-08-08 16:48:31.361', '2026-08-08 16:48:56.730', NULL), (15, '测试文章-CMS创建', 'CMS', '测试用的CMS文章', '# 测试文章\n\n这是一篇用于验证 CMS 文章创建功能的测试文章。', '', 1, 1, 'admin', 0, 0, 0, 0, 1, '2026-08-12 12:08:45.011', '2026-08-21 22:58:07.493', NULL), (19, '复现测试文章', '', '', '', '', 1, 1, 'admin', 0, 0, 0, 0, 0, '2026-08-22 17:39:49.064', '2026-08-22 17:39:49.064', '2026-08-22 17:39:49.206');

DROP TABLE IF EXISTS `cms_article_tag`;

CREATE TABLE `cms_article_tag` (
  `cms_article_id` bigint unsigned NOT NULL COMMENT '文章ID',
  `cms_tag_id` bigint unsigned NOT NULL COMMENT '标签ID',
  PRIMARY KEY (`cms_article_id`,`cms_tag_id`),
  KEY `fk_cms_article_tag_cms_tag` (`cms_tag_id`),
  CONSTRAINT `fk_cms_article_tag_cms_article` FOREIGN KEY (`cms_article_id`) REFERENCES `cms_article` (`id`),
  CONSTRAINT `fk_cms_article_tag_cms_tag` FOREIGN KEY (`cms_tag_id`) REFERENCES `cms_tag` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CMS文章-标签关联表';

DROP TABLE IF EXISTS `cms_category`;

CREATE TABLE `cms_category` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `parent_id` bigint unsigned DEFAULT '0' COMMENT '父分类ID(0为根)',
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分类名称',
  `slug` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL别名',
  `sort` bigint DEFAULT '0' COMMENT '排序',
  `status` tinyint DEFAULT '1' COMMENT '1启用 0禁用',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_cms_category_slug` (`slug`),
  KEY `idx_cms_category_parent_id` (`parent_id`),
  KEY `idx_cms_category_created_at` (`created_at`),
  KEY `idx_cms_category_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='文章分类';

