DROP TABLE IF EXISTS `cms_page`;

CREATE TABLE `cms_page` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `slug` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL别名',
  `link_type` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT 'page' COMMENT 'page内部页/link外部链接',
  `external_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '外部链接URL',
  `content` longtext COLLATE utf8mb4_unicode_ci COMMENT '正文',
  `status` tinyint DEFAULT '1' COMMENT '1启用 0禁用',
  `sort` bigint DEFAULT '0' COMMENT '排序',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_cms_page_slug` (`slug`),
  KEY `idx_cms_page_created_at` (`created_at`),
  KEY `idx_cms_page_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='单页';

INSERT INTO `cms_page` (`id`, `title`, `slug`, `link_type`, `external_url`, `content`, `status`, `sort`, `created_at`, `updated_at`, `deleted_at`) VALUES (1, '关于我们', 'about', 'page', '', '# 关于我们\n\n**河南爱编网络科技股份有限公司**是一家专注于企业数字化的软件开发公司，位于河南省洛阳市。我们既打造自研产品 **行简**，也面向企业客户承接各类**软件定制开发**与**项目外包**业务。\n\n## 自研产品：行简\n\n**行简**是一站式企业管理平台，为中小企业提供**私有化部署**的全模块业务管理系统。\n\n### 我们解决什么问题\n\n很多企业在用 **3-5 个 SaaS 拼凑**管理业务：CRM 用一个、审批用一个、进销存用一个、财务用一个。结果是数据不通、来回切换、年年付费。\n\n行简把 **CRM、审批流、进销存、财务、HRM、OA、官网 CMS** 全部放在一个系统里，**一套搞定**，数据天然打通。\n\n### 核心特点\n\n| 特点 | 说明 |\n| --- | --- |\n| 🔒 **私有化部署** | 源码部署到客户自己的服务器，数据完全归企业所有，不依赖第三方云 |\n| 🧩 **全模块一体化** | 13 个业务模块一个系统，告别数据孤岛和 SaaS 拼凑 |\n| 👥 **精细权限控制** | 基于角色的权限管理(RBAC) + 数据范围控制，按部门/本人隔离数据 |\n| 🏆 **AI 原生支持** | 内置 MCP 协议，Claude / Cursor / Codex 可直连操作业务数据 |\n| 💰 **软件免费** | 不限用户数、不限模块，只收 1000 元一次性部署服务费 |\n\n### 技术栈\n\n- **后端**：Go 1.25 + Gin + GORM + Casbin + Redis\n- **管理后台**：React 19 + TypeScript + Ant Design Pro\n- **企业官网**：Next.js 15 + Tailwind CSS\n- **移动端**：React 19 + Ant Design Mobile\n\n## 软件开发业务\n\n除了自研产品，我们还承接软件定制开发与项目外包，提供从需求分析、方案设计、开发测试到部署运维的一站式服务：\n\n- 🏗️ **业务系统定制开发**：CRM、ERP、OA、进销存、项目管理等企业管理系统按需定制\n- 🌐 **网站与小程序开发**：企业官网、H5 应用、微信小程序、移动 App\n- 🔧 **系统集成与二次开发**：与现有系统对接、数据迁移、功能扩展、私有化部署实施\n- 💼 **项目外包承接**：项目整包外包、模块开发外包、驻场/远程开发人力支持，按项目或按人天灵活合作\n- 🤝 **长期技术支持**：运维保障、迭代升级、技术咨询服务\n\n**服务流程**：需求沟通 → 方案与报价 → 设计开发 → 测试交付 → 上线运维\n\n如果您有软件开发需求，欢迎[联系我们](/contact)，我们将尽快为您评估与报价。\n\n## 公司信息\n\n**河南爱编网络科技股份有限公司**，位于河南省洛阳市。\n\n- 官网：[devlovecode.com](https://devlovecode.com)\n- 邮箱：shichenyang@devlovecode.com\n- 电话：15139960649\n- ICP 备案：豫ICP备2024074107号-2\n', 1, 1, '2026-08-05 09:52:36.368', '2026-08-20 20:16:29.489', NULL), (2, '文档中心', 'docs', 'link', 'https://docs.devlovecode.com', '', 1, 0, '2026-08-06 12:24:20.770', '2026-08-06 12:24:20.770', NULL), (3, '在线体验', 'demo', 'page', '', '# 在线体验行简\n\n无需注册，直接登录体验完整的企业管理平台。\n\n## 🔗 立即体验\n\n点击下方链接进入管理系统后台：\n\n**[→ 进入管理后台](https://admin.devlovecode.com/)**\n\n## 🔑 体验账号\n\n| 账号 | 密码 | 角色 | 可体验内容 |\n| --- | --- | --- | --- |\n| `zhangsan` | `qzt123456` | 销售 | CRM 全流程：线索 → 客户 → 商机 → 合同 |\n\n> 体验账号为**销售角色**，可浏览 CRM 模块全部功能。\n\n## 📋 你能看到什么\n\n### CRM 客户管理\n- **线索管理**：线索录入、跟进、转化、公海池\n- **客户管理**：客户分级、跟进记录、公海回收\n- **商机管理**：商机漏斗、阶段流转、成交概率\n- **合同管理**：合同签订、回款计划、回款记录\n\n### 工作台\n- 核心指标卡片（客户/商机/合同/回款汇总）\n- 近 30 天回款趋势图\n- 商机漏斗可视化\n- 审批待办与消息通知\n\n### 其他\n- 日历视图\n- 个人中心（含 API Key 与 MCP 配置）\n\n---\n\n## 💬 想要完整体验？联系我们\n\n体验账号只开放了 CRM 模块（销售角色）。如果你需要体验**全部 13 个模块**，或者想**在自己的服务器上部署**，随时联系我们：\n\n| 联系方式 | |\n| --- | --- |\n| 📞 **电话** | [15139960649](tel:15139960649) |\n| 📧 **邮箱** | [shichenyang@devlovecode.com](mailto:shichenyang@devlovecode.com) |\n| 📍 **地址** | 河南省洛阳市 |\n\n**1000 元一次性部署费**，源码级交付到你的服务器，数据完全归你所有。当天部署当天用。\n\n---\n\n## 🔥 限时优惠\n\n现在联系我们，享受以下权益：\n\n- ✅ **软件免费**（不限用户数、不限模块）\n- ✅ **1000 元全包部署服务费**（部署+初始化+培训）\n- ✅ **免费 1 次定制需求**（价值 1000 元）\n- ✅ **1 对 1 使用培训**\n\n> 名额有限，先到先得。我们每多服务一家企业，产品就多一份打磨。', 1, 0, '2026-08-08 16:27:38.472', '2026-08-12 12:08:55.029', NULL), (4, '1', '11', 'link', '111', '', 0, 0, '2026-08-22 16:06:39.511', '2026-08-22 16:19:45.999', '2026-08-22 16:20:14.630');

DROP TABLE IF EXISTS `cms_tag`;

CREATE TABLE `cms_tag` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标签名称',
  `slug` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL别名',
  `sort` bigint DEFAULT '0' COMMENT '排序',
  `status` tinyint DEFAULT '1' COMMENT '1启用 0禁用',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_cms_tag_slug` (`slug`),
  KEY `idx_cms_tag_created_at` (`created_at`),
  KEY `idx_cms_tag_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='标签';

