DROP TABLE IF EXISTS `crm_contract_item`;

CREATE TABLE `crm_contract_item` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `contract_id` bigint unsigned NOT NULL COMMENT '合同ID',
  `product_id` bigint unsigned DEFAULT NULL COMMENT '关联产品ID',
  `product_name` varchar(255) NOT NULL COMMENT '产品名称',
  `quantity` decimal(14,2) NOT NULL DEFAULT '1.00' COMMENT '数量',
  `unit` varchar(20) DEFAULT NULL COMMENT '单位',
  `unit_price` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '单价',
  `amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '小计(数量*单价)',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_contract_item_contract` (`contract_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='合同产品明细';

