DROP TABLE IF EXISTS `crm_contract_payment_plan`;

CREATE TABLE `crm_contract_payment_plan` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `contract_id` bigint unsigned NOT NULL COMMENT '合同ID',
  `plan_date` date NOT NULL COMMENT '计划回款日期',
  `plan_amount` decimal(14,2) NOT NULL COMMENT '计划金额',
  `received_amount` decimal(14,2) DEFAULT '0.00' COMMENT '已回款金额(累计维护)',
  `status` tinyint DEFAULT '0' COMMENT '0未回款 1部分 2已回款',
  `remark` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_crm_contract_payment_plan_contract_id` (`contract_id`),
  KEY `idx_crm_contract_payment_plan_created_at` (`created_at`),
  KEY `idx_crm_contract_payment_plan_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='回款计划';

