DROP TABLE IF EXISTS `crm_contract_payment_record`;

CREATE TABLE `crm_contract_payment_record` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `contract_id` bigint unsigned NOT NULL COMMENT '合同ID',
  `plan_id` bigint unsigned DEFAULT NULL COMMENT '关联回款计划(可选)',
  `received_date` date NOT NULL COMMENT '实际回款日期',
  `amount` decimal(14,2) NOT NULL COMMENT '回款金额',
  `method` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '回款方式(字典PAYMENT_METHOD)',
  `remark` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_crm_contract_payment_record_contract_id` (`contract_id`),
  KEY `idx_crm_contract_payment_record_plan_id` (`plan_id`),
  KEY `idx_crm_contract_payment_record_created_at` (`created_at`),
  KEY `idx_crm_contract_payment_record_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='回款记录';

