DROP TABLE IF EXISTS `crm_contract_template`;

CREATE TABLE `crm_contract_template` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(255) NOT NULL COMMENT '模板名称',
  `content` longtext NOT NULL COMMENT 'Markdown正文(含${变量}占位符)',
  `remark` varchar(500) DEFAULT NULL COMMENT '说明',
  `enabled` tinyint NOT NULL DEFAULT '1' COMMENT '1启用 0停用',
  `owner_id` bigint unsigned DEFAULT NULL COMMENT '创建人',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_ct_enabled` (`enabled`,`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='合同模板';

INSERT INTO `crm_contract_template` (`id`, `name`, `content`, `remark`, `enabled`, `owner_id`, `created_at`, `updated_at`, `deleted_at`) VALUES (1, '软件服务合同（标准模板）', 'sadfas ${contractNo}${startDate}${stage}', '软件部署服务合同标准模板，含 ${变量} 占位符，套打时自动替换', 1, 1, '2026-08-04 20:07:00.209', '2026-08-06 16:15:16.052', NULL), (2, '技术服务合同（标准模板）', '# 技术服务合同\n\n**合同编号：** ${contractNo}\n\n甲方（委托方）：${customerName}\n统一社会信用代码/税号：${taxNo}\n地址：${titleAddress}\n电话：${titlePhone}\n开户行：${bankName}\n银行账号：${bankAccount}\n\n乙方（服务方）：${titleName}\n地址：${titleAddress}\n电话：${titlePhone}\n\n## 第一条 服务内容\n\n甲方委托乙方提供技术服务，具体服务内容、技术指标及验收标准以双方确认的技术方案为准。\n\n## 第二条 服务期限\n\n本合同服务期限自 **${startDate}** 起至 **${endDate}** 止。合同期满前30日，双方可协商续签事宜。\n\n## 第三条 合同金额及支付方式\n\n1. 本合同技术服务总金额为 **¥${totalAmount}** 元（大写：人民币 元整），含税。\n2. 支付方式：按双方约定节点分期支付，具体如下：\n   - 合同签订后支付首付款；\n   - 服务验收合格后支付尾款。\n3. 甲方每次付款前，乙方应开具等额合法有效的增值税发票。\n\n## 第四条 双方权利义务\n\n### 4.1 甲方权利义务\n1. 及时向乙方提供开展技术服务所需的资料、数据及必要的配合；\n2. 按合同约定及时足额支付服务费用；\n3. 对乙方提供的服务成果及时组织验收。\n\n### 4.2 乙方权利义务\n1. 按约定时间、标准完成技术服务并交付成果；\n2. 对甲方提供的资料、数据保密，未经甲方书面同意不得向第三方披露；\n3. 保证服务成果不侵犯任何第三方知识产权。\n\n## 第五条 验收\n\n服务完成后，甲方应在 **7个工作日** 内组织验收。逾期未验收且未提出书面异议的，视为验收合格。\n\n## 第六条 违约责任\n\n1. 乙方未按约定提供服务或服务成果不合格的，应负责整改直至合格，逾期超过15日的，甲方有权解除合同并要求退还相应款项；\n2. 甲方逾期付款的，每逾期一日按未付款项的 **0.05%** 支付违约金；\n3. 任何一方违反保密义务给对方造成损失的，应承担赔偿责任。\n\n## 第七条 知识产权\n\n服务过程中产生的技术成果及知识产权归属，按双方另行签订的知识产权协议约定执行；未约定的，依相关法律法规确定。\n\n## 第八条 保密条款\n\n双方对本合同内容及履行过程中知悉的对方商业秘密负有保密义务，保密期限自合同生效之日起 **3年**。\n\n## 第九条 争议解决\n\n因本合同引起的争议，双方应友好协商解决；协商不成的，任何一方均可向 **乙方所在地** 人民法院提起诉讼。\n\n## 第十条 其他\n\n1. 本合同一式 **贰** 份，甲乙双方各执 **壹** 份，具有同等法律效力；\n2. 本合同自双方签字（盖章）之日起生效；\n3. 未尽事宜，双方可签订补充协议，补充协议与本合同具有同等法律效力。\n\n甲方（盖章）：${customerName}    乙方（盖章）：${titleName}\n\n授权代表：                    授权代表：\n\n签订日期：${signedDate}    签订日期：${signedDate}\n', '技术服务合同标准模板，含 ${变量} 占位符，套打时自动替换', 1, 1, '2026-08-06 13:04:46.859', '2026-08-06 13:04:46.859', NULL), (3, '1', '11', '', 1, 1, '2026-08-18 20:07:23.102', '2026-08-18 20:07:23.102', '2026-08-18 20:45:45.329'), (4, '2', '22', '', 1, 1, '2026-08-18 20:08:28.713', '2026-08-18 20:08:28.713', '2026-08-18 20:45:41.937'), (5, '3', '33', '', 1, 1, '2026-08-18 20:10:20.712', '2026-08-18 20:10:20.712', '2026-08-18 20:45:39.941'), (6, '4', '44', '', 1, 1, '2026-08-18 20:10:29.892', '2026-08-18 20:10:29.892', '2026-08-18 20:45:37.831'), (7, '5', '55', '', 1, 1, '2026-08-18 20:38:23.342', '2026-08-18 20:38:23.342', '2026-08-18 20:45:35.489'), (8, '6', '66', '', 1, 1, '2026-08-18 20:38:37.064', '2026-08-18 20:38:37.064', '2026-08-18 20:45:33.568'), (9, '7', '77', '', 1, 1, '2026-08-18 20:39:29.958', '2026-08-18 20:39:29.958', '2026-08-18 20:45:30.611'), (10, '8', '888', '8888', 1, 1, '2026-08-18 20:39:52.874', '2026-08-18 20:43:30.839', '2026-08-18 20:45:27.721'), (11, '9', '99', '', 1, 1, '2026-08-18 20:40:05.275', '2026-08-18 20:40:05.275', '2026-08-18 20:44:33.929'), (12, '回归模板F', '甲方:{{客户名称}} v2', '', 1, 5, '2026-08-28 20:32:53.037', '2026-08-28 20:38:28.055', '2026-08-28 20:40:19.618'), (13, '回归R6模板', '# 回归R6模板 甲方:${customerName} 编号:${contractNo}', '', 1, 5, '2026-09-02 00:29:21.003', '2026-09-02 00:29:21.003', '2026-09-02 00:33:25.971'), (14, '回归R6模板v2', '# 回归R6模板 甲方:${customerName} 编号:${contractNo}', '', 1, 5, '2026-09-02 00:29:54.940', '2026-09-02 00:31:48.947', '2026-09-02 00:31:55.658'), (15, '回归R7模板v2', '# 回归R7模板 ${customerName}', '', 1, 5, '2026-09-02 10:49:03.544', '2026-09-02 10:49:10.439', '2026-09-02 10:49:17.306');

DROP TABLE IF EXISTS `crm_customer`;

CREATE TABLE `crm_customer` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户名称',
  `customer_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户编号',
  `level` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户级别(字典CUSTOMER_LEVEL)',
  `source` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户来源(字典CUSTOMER_SOURCE)',
  `status` tinyint DEFAULT '1' COMMENT '1正常 2冻结 3流失',
  `industry` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '行业(字典INDUSTRY)',
  `owner_id` bigint unsigned DEFAULT NULL COMMENT '负责人ID(公海时NULL)',
  `follower_id` bigint unsigned DEFAULT NULL COMMENT '最新跟进人ID',
  `follow_time` datetime DEFAULT NULL COMMENT '最新跟进时间',
  `in_pool` tinyint DEFAULT '0' COMMENT '0私海 1公海',
  `pool_id` bigint unsigned DEFAULT NULL COMMENT '公海ID',
  `collection_time` datetime(3) DEFAULT NULL COMMENT '领取时间',
  `pool_reason` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '进公海原因',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_crm_customer_level` (`level`),
  KEY `idx_crm_customer_industry` (`industry`),
  KEY `idx_owner` (`owner_id`),
  KEY `idx_pool` (`in_pool`,`pool_id`),
  KEY `idx_crm_customer_created_at` (`created_at`),
  KEY `idx_crm_customer_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=81 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CRM 客户';

