DROP TABLE IF EXISTS `crm_customer_pool`;

CREATE TABLE `crm_customer_pool` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公海名称',
  `scope_dept_ids` text COLLATE utf8mb4_unicode_ci COMMENT '可见部门ID集合(JSON数组)',
  `scope_role_ids` text COLLATE utf8mb4_unicode_ci COMMENT '可见角色ID集合(JSON数组)',
  `admin_user_ids` text COLLATE utf8mb4_unicode_ci COMMENT '管理员用户ID集合(JSON数组)',
  `enabled` tinyint DEFAULT NULL COMMENT '1启用 0禁用',
  `auto_recycle` tinyint DEFAULT NULL COMMENT '1开启自动回收 0关闭',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  `is_default` tinyint DEFAULT '0' COMMENT '是否默认池(不可删)',
  PRIMARY KEY (`id`),
  KEY `idx_crm_customer_pool_enabled` (`enabled`),
  KEY `idx_crm_customer_pool_created_at` (`created_at`),
  KEY `idx_crm_customer_pool_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='公海池配置';

INSERT INTO `crm_customer_pool` (`id`, `name`, `scope_dept_ids`, `scope_role_ids`, `admin_user_ids`, `enabled`, `auto_recycle`, `created_at`, `updated_at`, `deleted_at`, `is_default`) VALUES (1, '默认公海', '', '', '', 1, 1, '2026-08-03 12:54:45.042', '2026-08-14 10:40:08.484', NULL, 1), (11, '1', '[5,4]', '[3,4]', '[3,1]', 1, 0, '2026-08-18 21:28:58.924', '2026-08-18 21:34:46.142', '2026-08-18 21:36:10.466', 0), (12, '2', '', '', '', 1, 0, '2026-08-18 21:33:29.309', '2026-08-18 21:33:29.309', '2026-08-18 21:36:12.753', 0);

DROP TABLE IF EXISTS `crm_customer_pool_hidden_field`;

CREATE TABLE `crm_customer_pool_hidden_field` (
  `pool_id` bigint unsigned NOT NULL COMMENT '公海池ID',
  `field_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '自定义字段ID',
  PRIMARY KEY (`pool_id`,`field_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='公海隐藏字段(复合主键 pool_id + field_id)';

DROP TABLE IF EXISTS `crm_customer_pool_pick_rule`;

CREATE TABLE `crm_customer_pool_pick_rule` (
  `pool_id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '公海池ID(主键,1:1)',
  `limit_daily` tinyint DEFAULT '0' COMMENT '1限制每日领取数',
  `daily_limit` bigint DEFAULT '0' COMMENT '每日领取上限',
  `limit_prev_owner` tinyint DEFAULT '0' COMMENT '1限制前归属人领取',
  `prev_owner_interval` bigint DEFAULT '0' COMMENT '前归属人重新领取间隔天数',
  `limit_new_data` tinyint DEFAULT '0' COMMENT '1限制新数据冷却期',
  `new_data_interval` bigint DEFAULT '0' COMMENT '新数据冷却天数',
  PRIMARY KEY (`pool_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='领取规则(1:1 with pool,pool_id 主键)';

DROP TABLE IF EXISTS `crm_customer_pool_recycle_rule`;

CREATE TABLE `crm_customer_pool_recycle_rule` (
  `pool_id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '公海池ID(主键,1:1)',
  `operator` varchar(3) COLLATE utf8mb4_unicode_ci DEFAULT 'AND' COMMENT '多条件组合 AND/OR',
  `conditions` text COLLATE utf8mb4_unicode_ci COMMENT '回收条件JSON数组',
  PRIMARY KEY (`pool_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='回收规则(1:1 with pool)';

INSERT INTO `crm_customer_pool_recycle_rule` (`pool_id`, `operator`, `conditions`) VALUES (1, 'AND', '[{"timeField":"LAST_FOLLOW_TIME","operator":"DYNAMIC","value":"7","nullSatisfied":false}]');

DROP TABLE IF EXISTS `crm_lead`;

CREATE TABLE `crm_lead` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '线索名称',
  `lead_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '线索编号',
  `contact_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系人姓名',
  `phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '电话',
  `email` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮箱',
  `company` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公司',
  `level` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '线索级别(字典LEAD_LEVEL)',
  `source` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '线索来源(字典LEAD_SOURCE)',
  `status` tinyint DEFAULT '1' COMMENT '1新建 2跟进中 3已转化 4无效',
  `industry` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '行业(字典INDUSTRY)',
  `owner_id` bigint unsigned DEFAULT NULL COMMENT '负责人ID(公海时NULL)',
  `follower_id` bigint unsigned DEFAULT NULL COMMENT '最新跟进人ID',
  `follow_time` datetime DEFAULT NULL COMMENT '最新跟进时间',
  `in_pool` tinyint DEFAULT '0' COMMENT '0私海 1公海',
  `pool_id` bigint unsigned DEFAULT NULL COMMENT '线索公海ID',
  `collection_time` datetime DEFAULT NULL COMMENT '领取时间',
  `pool_reason` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '进公海原因',
  `converted_customer_id` bigint unsigned DEFAULT NULL COMMENT '转化后的客户ID',
  `converted_at` datetime DEFAULT NULL COMMENT '转化时间',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  `remark` text COLLATE utf8mb4_unicode_ci COMMENT '留言内容(官网表单)',
  PRIMARY KEY (`id`),
  KEY `idx_lead_lead_level` (`level`),
  KEY `idx_lead_industry` (`industry`),
  KEY `idx_lead_owner` (`owner_id`),
  KEY `idx_lead_pool` (`in_pool`,`pool_id`),
  KEY `idx_lead_converted_customer_id` (`converted_customer_id`),
  KEY `idx_crm_lead_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=441 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CRM 线索';

DROP TABLE IF EXISTS `crm_lead_owner_history`;

CREATE TABLE `crm_lead_owner_history` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `lead_id` bigint unsigned NOT NULL COMMENT '线索ID',
  `owner_id` bigint unsigned DEFAULT NULL COMMENT '当时的负责人(进公海时NULL)',
  `action` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'TAKE/RELEASE/TRANSFER/RECYCLE',
  `operator_id` bigint unsigned NOT NULL COMMENT '操作人',
  `reason` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原因',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_crm_lead_owner_history_lead_id` (`lead_id`),
  KEY `idx_crm_lead_owner_history_owner_id` (`owner_id`),
  KEY `idx_crm_lead_owner_history_action` (`action`),
  KEY `idx_crm_lead_owner_history_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=451 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CRM 线索归属历史';

DROP TABLE IF EXISTS `crm_lead_pool`;

CREATE TABLE `crm_lead_pool` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公海名称',
  `scope_dept_ids` text COLLATE utf8mb4_unicode_ci COMMENT '可见部门ID集合(JSON数组)',
  `scope_role_ids` text COLLATE utf8mb4_unicode_ci COMMENT '可见角色ID集合(JSON数组)',
  `admin_user_ids` text COLLATE utf8mb4_unicode_ci COMMENT '管理员用户ID集合(JSON数组)',
  `enabled` tinyint DEFAULT NULL COMMENT '1启用 0禁用',
  `auto_recycle` tinyint DEFAULT NULL COMMENT '1开启自动回收 0关闭',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  `is_default` tinyint DEFAULT '0' COMMENT '是否默认池(不可删)',
  PRIMARY KEY (`id`),
  KEY `idx_crm_lead_pool_enabled` (`enabled`),
  KEY `idx_crm_lead_pool_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CRM 线索公海池';

