DROP TABLE IF EXISTS `crm_lead_pool_pick_rule`;

CREATE TABLE `crm_lead_pool_pick_rule` (
  `pool_id` bigint unsigned NOT NULL COMMENT '线索公海池ID(主键,1:1)',
  `limit_daily` tinyint DEFAULT '0' COMMENT '1限制每日领取数',
  `daily_limit` bigint DEFAULT '0' COMMENT '每日领取上限',
  `limit_prev_owner` tinyint DEFAULT '0' COMMENT '1限制前归属人领取',
  `prev_owner_interval` bigint DEFAULT '0' COMMENT '前归属人重新领取间隔天数',
  `limit_new_data` tinyint DEFAULT '0' COMMENT '1限制新数据冷却期',
  `new_data_interval` bigint DEFAULT '0' COMMENT '新数据冷却天数',
  PRIMARY KEY (`pool_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CRM 线索领取规则';

DROP TABLE IF EXISTS `crm_lead_pool_recycle_rule`;

CREATE TABLE `crm_lead_pool_recycle_rule` (
  `pool_id` bigint unsigned NOT NULL COMMENT '线索公海池ID(主键,1:1)',
  `operator` varchar(3) COLLATE utf8mb4_unicode_ci DEFAULT 'AND' COMMENT '多条件组合 AND/OR',
  `conditions` text COLLATE utf8mb4_unicode_ci COMMENT '回收条件JSON数组',
  PRIMARY KEY (`pool_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CRM 线索回收规则';

INSERT INTO `crm_lead_pool_recycle_rule` (`pool_id`, `operator`, `conditions`) VALUES (1, 'AND', '[{"timeField":"LAST_FOLLOW_TIME","operator":"DYNAMIC","value":"15","nullSatisfied":false}]');

DROP TABLE IF EXISTS `crm_opportunity`;

CREATE TABLE `crm_opportunity` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商机名称',
  `opportunity_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商机编号',
  `customer_id` bigint unsigned NOT NULL COMMENT '关联客户ID',
  `expected_amount` decimal(14,2) DEFAULT NULL COMMENT '预计金额',
  `expected_close_date` date DEFAULT NULL COMMENT '预计成交日期',
  `stage` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PROSPECTING' COMMENT '阶段(字典OPPORTUNITY_STAGE)',
  `probability` bigint DEFAULT NULL COMMENT '成交概率0-100',
  `owner_id` bigint unsigned DEFAULT NULL COMMENT '负责人',
  `follower_id` bigint unsigned DEFAULT NULL COMMENT '最新跟进人',
  `follow_time` datetime(3) DEFAULT NULL COMMENT '最新跟进时间',
  `source_clue_id` bigint unsigned DEFAULT NULL COMMENT '来源线索ID',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '描述',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_opp_customer` (`customer_id`),
  KEY `idx_opp_stage` (`stage`),
  KEY `idx_opp_owner` (`owner_id`),
  KEY `idx_crm_opportunity_created_at` (`created_at`),
  KEY `idx_crm_opportunity_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CRM 商机';

