, NULL, NULL, NULL, '', '2026-08-18 17:50:25.014', '2026-08-18 17:50:25.014', '2026-08-18 18:09:59.829'), (20, '7', 'SJ20260818007', 15, 0.00, NULL, 'PROSPECTING', NULL, 1, NULL, NULL, NULL, '', '2026-08-18 17:50:34.146', '2026-08-18 17:50:34.146', '2026-08-18 18:09:57.732'), (21, '8', 'SJ20260818008', 14, 0.00, NULL, 'PROSPECTING', NULL, 1, NULL, NULL, NULL, '', '2026-08-18 17:50:45.918', '2026-08-18 17:50:45.918', '2026-08-18 18:09:55.708'), (22, '9', 'SJ20260818009', 12, 0.00, NULL, 'PROSPECTING', NULL, 1, NULL, NULL, NULL, '', '2026-08-18 18:05:45.267', '2026-08-18 18:05:45.267', '2026-08-18 18:06:16.374');

DROP TABLE IF EXISTS `crm_product`;

CREATE TABLE `crm_product` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产品名称',
  `product_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品编号',
  `category` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分类(字典PRODUCT_CATEGORY)',
  `unit` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位',
  `standard_price` decimal(14,2) DEFAULT NULL COMMENT '标准价格',
  `cost_price` decimal(14,2) DEFAULT NULL COMMENT '成本价',
  `status` tinyint DEFAULT '1' COMMENT '1上架 2下架',
  `image_url` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商品主图URL',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '描述',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_crm_product_name` (`name`),
  KEY `idx_crm_product_category` (`category`),
  KEY `idx_crm_product_status` (`status`),
  KEY `idx_crm_product_created_at` (`created_at`),
  KEY `idx_crm_product_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CRM 商品';

INSERT INTO `crm_product` (`id`, `name`, `product_no`, `category`, `unit`, `standard_price`, `cost_price`, `status`, `image_url`, `description`, `created_at`, `updated_at`, `deleted_at`) VALUES (1, '行简一体化管理平台', 'QZT-SOFT-001', '软件产品', '套', 1000.00, 0.00, 1, 'https://cdn.devlovecode.com/product/42736e7a60685ef01a9fb47189901f4d.png', '# 行简一体化管理平台\n\n整套企业管理软件，**软件提供给企业使用**，只收一次性部署服务费。包含 CRM 客户管理、审批流、进销存、财务、HRM、CMS 官网等全套模块，源码级交付部署到客户自己的阿里云。\n\n## 收费模式\n\n| 项目 | 内容 | 费用 |\n| --- | --- | --- |\n| 平台软件 | 全部功能模块，不限用户数 | **面议** |\n| 部署服务费 | 一次性部署、数据初始化、使用培训 | 1000 元 |\n| 定制开发 | 后续追加功能按人天计费 | 面谈 |\n\n## 客户需自备的阿里云资源\n\n- **2C4G 云服务器 ECS** 一台（部署应用与数据库以外的全部服务）\n- **2C2G MySQL RDS** 实例一个\n- **OSS 对象存储** + **CDN 加速**（图片与静态资源）\n- **域名**一个（没有的话我们可以帮忙申请与备案）\n- 阿里云账号保留 **500 元余额**即可覆盖上述资源的基础开销\n\n> 以上资源我们都可以协助申请、配置与调优，客户不需要任何运维经验。\n\n## 平台功能预览\n\n### 客户管理\n\n线索、公海、客户、联系人、跟进记录全生命周期管理，支持自定义字段与自定义表单。\n\n![客户管理](https://cdn.devlovecode.com/product/9cedba50243387cff6152a732ab233d1.png)\n\n### 自定义字段设计器\n\n三栏式设计器：左侧字段类型、中间表单实时预览、右侧属性编辑，业务人员零代码即可扩展表单。\n\n![自定义字段设计器](https://cdn.devlovecode.com/product/6a4f63050a76fbbfac354b9e975725ba.png)\n\n### 审批流程设计器\n\n可视化拖拽画布设计审批流，支持审批节点、条件分支、多人会签/或签/依次审批。\n\n![审批流程设计器](https://cdn.devlovecode.com/product/327cf85332b04b1ad20a277208135a92.png)\n\n### 商品与内容管理\n\n商品支持主图上传（OSS + CDN 加速）与 Markdown 富文本详情，一键同步到企业官网展示。\n\n![商品管理](https://cdn.devlovecode.com/product/a348946d68f5d88ee70dd4ef8f6a0023.png)\n\n### 工作台\n\n数据看板、待办审批、快捷入口一屏聚合。\n\n![工作台](https://cdn.devlovecode.com/product/42736e7a60685ef01a9fb47189901f4d.png)\n\n---\n\n**总计投入：1000 元服务费 + 阿里云基础资源，即可拥有一套属于自己的企业管理系统。**', '2026-08-04 16:32:45.959', '2026-09-08 11:21:12.053', NULL), (3, '测试产品-标准', '', '', '', 0.00, 0.00, 2, '', '', '2026-08-12 12:08:00.708', '2026-08-12 12:08:02.989', '2026-08-16 21:47:29.557'), (4, '1', 'CP20260818001', '', '', 0.00, 0.00, 1, '', '', '2026-08-18 20:56:37.955', '2026-08-18 20:56:37.955', '2026-08-18 21:17:09.407'), (5, '2', 'CP20260818002', '', '', 0.00, 0.00, 1, '', '', '2026-08-18 20:56:55.433', '2026-08-18 20:56:55.433', '2026-08-18 21:17:07.460'), (6, '3', 'CP20260818003', '', '', 0.00, 0.00, 1, '', '', '2026-08-18 20:56:59.778', '2026-08-18 20:56:59.778', '2026-08-18 21:17:05.185'), (7, '4', 'CP20260818004', '', '', 0.00, 0.00, 1, '', '', '2026-08-18 20:57:03.815', '2026-08-18 20:57:03.815', '2026-08-18 21:17:02.915'), (8, '5', 'CP20260818005', '', '', 0.00, 0.00, 1, '', '', '2026-08-18 20:57:08.146', '2026-08-18 20:57:08.146', '2026-08-18 21:17:00.840'), (9, '6', 'CP20260818006', '', '', 0.00, 0.00, 1, '', '', '2026-08-18 20:57:13.011', '2026-08-18 20:57:13.011', '2026-08-18 21:16:58.640'), (10, '7', 'CP20260818007', '', '', 0.00, 0.00, 1, '', '', '2026-08-18 20:57:17.785', '2026-08-18 20:57:17.785', '2026-08-18 21:16:56.590'), (11, '8', 'CP20260818008', '', '', 0.00, 0.00, 1, '', '', '2026-08-18 20:57:23.483', '2026-08-18 20:57:23.483', '2026-08-18 21:16:54.425'), (12, '9', 'CP20260818009', '', '', 0.00, 0.00, 1, '', '', '2026-08-18 20:57:28.675', '2026-08-18 20:57:28.675', '2026-08-18 21:16:52.370'), (13, '10', 'CP20260818010', 'SERVICE', '', 0.00, 0.00, 1, '', '100', '2026-08-18 20:57:38.901', '2026-08-18 21:14:46.096', '2026-08-18 21:16:50.160'), (15, '云开发月度订阅', '', '', '', 0.00, 0.00, 2, '', '', '2026-08-31 15:25:50.599', '2026-08-31 15:39:35.431', '2026-08-31 15:43:38.479'), (16, '云开发服务', '', '', '', 0.00, 0.00, 2, '', '', '2026-08-31 15:32:48.676', '2026-08-31 15:39:35.435', '2026-08-31 15:43:36.995'), (17, '汉服软件部署服务', '', '', '', 0.00, 0.00, 2, '', '', '2026-08-31 15:32:58.594', '2026-08-31 15:39:35.433', '2026-08-31 15:43:35.566'), (18, '小程序云开发（个人版）', '', '', '', 0.00, 0.00, 2, '', '', '2026-08-31 15:35:48.091', '2026-08-31 15:39:35.431', '2026-08-31 15:43:34.232'), (19, '小程序企业认证', '', '', '', 0.00, 0.00, 2, '', '', '2026-08-31 15:36:06.199', '2026-08-31 15:39:35.435', '2026-08-31 15:43:32.095'), (20, '汉服软件部署实施服务', 'CP20260831006', '技术服务', '次', 500.00, 0.00, 1, 'https://cdn.devlovecode.com/product/20260831/697bcf82f32d136797b752479444b412.png', '# 「云裳记」汉服妆造预约小程序 · 部署实施服务\n\n一套面向**汉服体验馆 / 妆造工作室**的微信小程序预约系统。微信云开发全托管（云函数 + 云数据库 + 云存储），**无自建服务器、免域名备案、免运维**。本服务将整套系统部署到您自己的小程序账号与云开发环境，交付即可开门营业。\n\n## 收费模式\n\n| 项目 | 内容 | 费用 |\n| --- | --- | --- |\n| 部署实施 | 小程序发布、云函数部署、数据库初始化、管理端配置、店长培训 | **1000 元 / 次** |\n| 二次开发 | 新增功能、界面定制、对接其他系统 | 另行报价 |\n\n## 客户需自备的官方费用\n\n- **微信小程序账号**（企业认证，300 元/年认证费由微信官方收取）\n- **微信云开发环境**（按量付费，基础用量约 19.9 元/月起）\n- **微信支付商户号**（如需在线收款时绑定，可选）\n\n> 以上账号我们全程协助注册、认证与配置，客户不需要任何技术经验。\n\n## 小程序功能预览（顾客端）\n\n### 首页选款\n\n宋制 / 明制 / 唐制分类、本周精选、活动位与搜索，每套标注妆造时长与到店体验提示。\n\n![首页选款](https://cdn.devlovecode.com/product/20260831/697bcf82f32d136797b752479444b412.png)\n\n### 款式详情\n\n大图展示、尺码选择、服务标签（一客一消毒、免费改腰等），一键直达预约。\n\n![款式详情](https://cdn.devlovecode.com/product/20260831/4ae6b63083e1d0eca0bd32534b6e8324.png)\n\n### 妆造套餐\n\n简妆 / 全妆 / 盛典三档套餐明码标价，标注时长与「与套服同立省」提示，可现场升档。\n\n![妆造套餐](https://cdn.devlovecode.com/product/20260831/a787f43c940cf25307990692d196652c.png)\n\n### 到店预约\n\n选门店、指定妆造师（可免加价）、近 7 天日期与时段自助挑选；同一妆造师同一时段**防撞单**，先到先得。\n\n![到店预约](https://cdn.devlovecode.com/product/20260831/3bb3758036b013c661ddaacf30dae5bb.png)\n\n### 我的预约 · 到店核销凭证\n\n订单按「待体验 / 已完成 / 已取消」分类，到店出示订单详情页给店员核对即可，含温馨提示与取消规则。\n\n![我的预约](https://cdn.devlovecode.com/product/20260831/0802b0f1a7ec5ef33e1126ae5bed7a41.png)\n\n![订单详情](https://cdn.devlovecode.com/product/20260831/05476bff81a57699cda0d072acf14961.png)\n\n### 深色模式\n\n宣纸、墨、朱砂东方设计系统，自动跟随系统深浅色，夜间浏览不刺眼。\n\n![深色模式](https://cdn.devlovecode.com/product/20260831/7a552fca4ea4b0aec1500c00213cdb6e.png)\n\n## 店铺管理端（同样在小程序内）\n\n管理端无需下载 App，店长微信打开即用；管理员白名单鉴权，非授权人员不可见。\n\n### 管理台总览\n\n今日妆造师在岗、待办处理、快捷操作一屏聚合，数据来自云开发实时数据库。\n\n![管理台总览](https://cdn.devlovecode.com/product/20260831/5d11204039fe61c234af5bbb5ae958f0.png)\n\n### 预约排期\n\n按日查看时段容量与当日预约明细，一键核销完成；妆造师排班与可约时段模板自助维护。\n\n![预约排期](https://cdn.devlovecode.com/product/20260831/65cfde5c70bf1ff7127c0c519fc57aba.png)\n\n### 订单管理\n\n核销完成、穿着离店、取消等状态流转，支持一键**导出订单 CSV** 对账。\n\n![订单管理](https://cdn.devlovecode.com/product/20260831/e138e3813daf819055573cd274d2bdca.png)\n\n### 库存与上下架\n\n款式管理、价格调整、一键上下架，下架款式立即在小程序隐藏。\n\n![库存与上下架](https://cdn.devlovecode.com/product/20260831/b6ca0a2e63230358d7188e13342aad87.png)\n\n## 交付清单\n\n- 小程序源码部署至客户小程序账号，协助体验版与正式版发布审核\n- 6 个云函数部署：登录 / 商品目录 / 预约 / 管理端 / 支付 / 支付回调\n- 云数据库集合与索引初始化（预约表唯一索引，防止并发撞单）\n- 管理员白名单配置 + 店长线上培训（约 1 小时）\n- 微信支付接入指引（绑定商户号后即可在线预付与退款）\n\n---\n\n**总计投入：1000 元一次性服务费 + 微信官方基础费用，即可拥有属于自己店铺的预约小程序。**', '2026-08-31 15:37:46.711', '2026-08-31 16:14:33.753', NULL), (22, '桶装水软件部署实施服务', 'CP20260831007', '技术服务', '次', 500.00, 0.00, 1, 'https://cdn.devlovecode.com/product/20260831/d5e3629c6ad35dcc92e69e745f18f0ca.png', '# 「碧泉到家」桶装水配送小程序 · 部署实施服务\n\n一套面向**水站 / 桶装水配送商家**的微信小程序订水系统。顾客在线订水、购买水票，骑手接单配送，水站掌柜在小程序内直接经营——**用户端 + 配送端 + 管理端三端一体**。微信云开发全托管（云函数 + 云数据库 + 云存储），**无自建服务器、免域名备案、免运维**。本服务将整套系统部署到您自己的小程序账号与云开发环境，交付即可接单开送。\n\n## 收费模式\n\n| 项目 | 内容 | 费用 |\n| --- | --- | --- |\n| 部署实施 | 小程序发布、云函数部署、数据库初始化、管理端配置、店长培训 | **1000 元 / 次** |\n| 二次开发 | 新增功能、界面定制、对接其他系统 | 另行报价 |\n\n## 客户需自备的官方费用\n\n- **微信小程序账号**（企业认证，300 元/年认证费由微信官方收取）\n- **微信云开发环境**（按量付费，基础用量约 19.9 元/月起）\n- **微信支付商户号**（如需在线收款时绑定，可选）\n\n> 以上账号我们全程协助注册、认证与配置，客户不需要任何技术经验。\n\n## 小程序功能预览（顾客端）\n\n### 首页选购\n\n品牌分类筛选（农夫山泉 / 怡宝 / 百岁山等）、关键词搜索、商品加购与浮动结算条，加购即结算，地址栏自动定位门店服务范围。\n\n![首页选购](https://cdn.devlovecode.com/product/20260831/d5e3629c6ad35dcc92e69e745f18f0ca.png)\n\n### 水票系统\n\n买 10 送 1 的水票权益：购票入账、换水自动冻结核销、跨批次先进先出、过期自动清零，全程流水可查——水站的锁客神器。\n\n![水票权益](https://cdn.devlovecode.com/product/20260831/11b016711d6e97aa2899024eb4642188.png)\n\n### 确认订单 · 支付\n\n收货地址一键选用、送达时间段预约、优惠券自动抵扣、满 2 桶免配送费；微信支付快捷下单。\n\n![确认订单](https://cdn.devlovecode.com/product/20260831/99fd508719f0dbf660bb8d84c9a619d0.png)\n\n### 订单跟踪\n\n全部 / 待配送 / 配送中 / 已完成四态筛选；订单详情实时显示骑手与配送进度，支持在线取消（未配送单）、复制单号、一键「再来一单」。\n\n![订单列表](https://cdn.devlovecode.com/product/20260831/b537125d34c211196a901e1d3ffb6939.png)\n\n![订单详情 · 配送跟踪](https://cdn.devlovecode.com/product/20260831/4442882ce5fbac062ebcb9c8e4f739ef.png)\n\n### 收货地址管理\n\n多地址管理、默认地址切换、标签（家 / 公司），送水上门地址一键带入订单。\n\n![收货地址](https://cdn.devlovecode.com/product/20260831/8bea2b1da2eb4a35d5ff3634456aeb42.png)\n\n### 我的 · 会员资产\n\n余额、水票、优惠券统计与订单 / 地址 / 客服快捷入口，配送员与管理员入口按账号权限自动显示。\n\n![我的](https://cdn.devlovecode.com/product/20260831/871cb2d675bdb64263b83d6898d5ee02.png)\n\n## 配送员端（同一个小程序，身份自动识别）\n\n- **配送工作台**：接单开关（收工不再派单）、今日任务统计，待取货 / 配送中 / 已送达三态流转\n\n![配送工作台](https://cdn.devlovecode.com/product/20260831/b136bef916c871b1a9f997a41d35324c.png)\n\n- **配送执行**：路线示意、联系客户、导航上门、送达确认回执实时同步水站与顾客\n\n![配送执行](https://cdn.devlovecode.com/product/20260831/acdc5479568644a729e9c6716d97526a.png)\n\n- **防撞单**：同一订单多个骑手抢单只成功一人，系统级防重复\n\n## 管理端（同样在小程序内）\n\n- **经营工作台**：今日订单 / 营收 / 出库核心指标，近 7 日出库柱状图，库存水位预警，骑手在线状态\n\n![经营工作台](https://cdn.devlovecode.com/product/20260831/66afb92ae2b4b130eaba691c2b77153e.png)\n\n- **订单管理**：四态筛选、一键派单给指定骑手，派单后订单状态实时翻转\n\n![订单管理 · 派单](https://cdn.devlovecode.com/product/20260831/848a226cf5657e6a9751544d7f12269c.png)\n\n- 手机号即配送员身份关联，无需额外 App，掌柜微信打开即用\n\n## 交付清单\n\n- 小程序源码部署至客户小程序账号，协助体验版与正式版发布审核\n- 6 个云函数部署：登录 / 商城 / 会员 / 交易 / 配送 / 管理端\n- 云数据库集合与唯一索引初始化（订单防重、防超卖、防重复核销）\n- 管理员白名单配置 + 店长线上培训（约 1 小时）\n- 微信支付接入指引（绑定商户号后即可在线收款）\n\n---\n\n**总计投入：1000 元一次性服务费 + 微信官方基础费用，即可拥有属于自己水站的订水小程序。**', '2026-08-31 16:42:12.825', '2026-08-31 16:54:23.083', NULL), (23, '验证测试-半增量更新(临时)', 'CP20260831003', '验证改分类', '', 1.00, 0.00, 1, '', '', '2026-08-31 17:27:34.343', '2026-08-31 17:27:55.784', '2026-08-31 17:28:22.307');

DROP TABLE IF EXISTS `crm_product_sku`;

CREATE TABLE `crm_product_sku` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `product_id` bigint unsigned NOT NULL COMMENT '商品ID(引用crm_product.id)',
  `spec` varchar(128) NOT NULL DEFAULT '' COMMENT '规格描述(空=默认规格)',
  `sku_no` varchar(64) DEFAULT NULL COMMENT 'SKU编号',
  `price` decimal(14,2) DEFAULT NULL COMMENT '售价',
  `cost_price` decimal(14,2) DEFAULT NULL COMMENT '成本价',
  `image_url` varchar(512) DEFAULT NULL COMMENT '规格图URL',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sku_no` (`sku_no`),
  KEY `idx_product` (`product_id`),
  KEY `idx_crm_product_sku_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=29 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='商品规格SKU';

