DROP TABLE IF EXISTS `crm_ticket`;

CREATE TABLE `crm_ticket` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `ticket_no` varchar(64) NOT NULL COMMENT '工单编号',
  `title` varchar(200) NOT NULL COMMENT '标题',
  `description` varchar(2000) DEFAULT '' COMMENT '问题描述',
  `customer_id` bigint unsigned DEFAULT NULL COMMENT '客户ID',
  `customer_name` varchar(200) DEFAULT '' COMMENT '客户名称',
  `contract_id` bigint unsigned DEFAULT NULL COMMENT '关联合同ID',
  `contact_name` varchar(100) DEFAULT '' COMMENT '联系人',
  `contact_phone` varchar(50) DEFAULT '' COMMENT '联系电话',
  `category` varchar(32) DEFAULT '' COMMENT '问题类型',
  `priority` tinyint NOT NULL DEFAULT '2' COMMENT '1低2中3高4紧急',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1待处理2处理中3已解决4已关闭5已重开',
  `handler_id` bigint unsigned DEFAULT NULL COMMENT '处理人ID',
  `solution` varchar(2000) DEFAULT '' COMMENT '解决方案',
  `resolved_at` datetime DEFAULT NULL COMMENT '解决时间',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_crm_ticket_no` (`ticket_no`),
  KEY `idx_crm_ticket_customer` (`customer_id`),
  KEY `idx_crm_ticket_contract` (`contract_id`),
  KEY `idx_crm_ticket_status` (`status`),
  KEY `idx_crm_ticket_handler` (`handler_id`),
  KEY `idx_crm_ticket_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='CRM 售后工单';

