DROP TABLE IF EXISTS `crm_ticket_log`;

CREATE TABLE `crm_ticket_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `ticket_id` bigint unsigned NOT NULL COMMENT '工单ID',
  `content` varchar(2000) NOT NULL COMMENT '处理内容',
  `operator_id` bigint unsigned DEFAULT NULL COMMENT '操作人ID',
  `old_status` tinyint DEFAULT NULL COMMENT '变更前状态',
  `new_status` tinyint DEFAULT NULL COMMENT '变更后状态',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_crm_ticketlog_ticket` (`ticket_id`),
  KEY `idx_crm_ticketlog_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='CRM 工单处理日志';

