DROP TABLE IF EXISTS `customer_field`;

CREATE TABLE `customer_field` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID',
  `resource_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户ID',
  `field_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段ID',
  `field_value` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段值',
  PRIMARY KEY (`id`),
  KEY `idx_rfv` (`resource_id`,`field_id`,`field_value`),
  KEY `idx_customer_field_field_id` (`field_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='客户自定义字段值(单值)';

DROP TABLE IF EXISTS `customer_field_blob`;

CREATE TABLE `customer_field_blob` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID',
  `resource_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户ID',
  `field_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段定义ID(关联sys_module_field)',
  `field_value` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段值(大文本)',
  PRIMARY KEY (`id`),
  KEY `idx_customer_field_blob_resource_id` (`resource_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='客户自定义字段大值';

DROP TABLE IF EXISTS `fin_account`;

CREATE TABLE `fin_account` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '科目编码(如1001)',
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '科目名称',
  `type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ASSET/LIABILITY/EQUITY/INCOME/EXPENSE',
  `parent_id` bigint unsigned DEFAULT NULL COMMENT '上级科目ID',
  `balance_dir` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'DEBIT/CREDIT',
  `level` bigint DEFAULT '1' COMMENT '层级',
  `is_leaf` tinyint(1) DEFAULT '1' COMMENT '是否末级科目(凭证只能选末级)',
  `status` tinyint DEFAULT '1' COMMENT '1启用0禁用',
  `sort` bigint DEFAULT '0' COMMENT '排序号',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_fin_account_code` (`code`),
  KEY `idx_fin_account_type` (`type`),
  KEY `idx_fin_account_parent_id` (`parent_id`),
  KEY `idx_fin_account_created_at` (`created_at`),
  KEY `idx_fin_account_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='会计科目';

