DROP TABLE IF EXISTS `fin_receivable`;

CREATE TABLE `fin_receivable` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `doc_no` varchar(64) NOT NULL COMMENT '往来单号',
  `direction` varchar(20) NOT NULL COMMENT 'RECEIVABLE应收/PAYABLE应付',
  `party_type` varchar(20) DEFAULT '' COMMENT 'CUSTOMER/SUPPLIER/EMPLOYEE',
  `party_id` bigint unsigned DEFAULT NULL COMMENT '往来方ID',
  `party_name` varchar(200) DEFAULT '' COMMENT '往来方名称',
  `occur_date` date NOT NULL COMMENT '发生日期',
  `due_date` date DEFAULT NULL COMMENT '到期日期',
  `original_amount` decimal(14,2) NOT NULL COMMENT '原始金额',
  `settled_amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '已结算金额',
  `biz_type` varchar(32) DEFAULT '' COMMENT 'CONTRACT/PURCHASE_ORDER/LOAN等',
  `biz_id` bigint unsigned DEFAULT NULL COMMENT '业务单据ID',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0未结算1部分2已结清',
  `remark` varchar(500) DEFAULT '' COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_fin_recv_doc` (`doc_no`),
  KEY `idx_fin_recv_direction` (`direction`),
  KEY `idx_fin_recv_party` (`party_id`),
  KEY `idx_fin_recv_status` (`status`),
  KEY `idx_fin_recv_biz` (`biz_id`),
  KEY `idx_fin_recv_occur` (`occur_date`),
  KEY `idx_fin_recv_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='应收应付往来台账';

