DROP TABLE IF EXISTS `follow_up_record_field`;

CREATE TABLE `follow_up_record_field` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID',
  `resource_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '跟进记录ID',
  `field_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段定义ID(关联sys_module_field)',
  `field_value` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段值',
  PRIMARY KEY (`id`),
  KEY `idx_f_rfv` (`resource_id`,`field_id`,`field_value`),
  KEY `idx_follow_up_record_field_field_id` (`field_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='跟进记录自定义字段值';

DROP TABLE IF EXISTS `follow_up_record_field_blob`;

CREATE TABLE `follow_up_record_field_blob` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID',
  `resource_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '跟进记录ID',
  `field_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段定义ID(关联sys_module_field)',
  `field_value` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段值(大文本)',
  PRIMARY KEY (`id`),
  KEY `idx_follow_up_record_field_blob_resource_id` (`resource_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='跟进记录自定义字段大值';

DROP TABLE IF EXISTS `hrm_attendance_clock`;

CREATE TABLE `hrm_attendance_clock` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `employee_id` bigint unsigned NOT NULL COMMENT '员工ID',
  `clock_date` date NOT NULL COMMENT '打卡日期',
  `clock_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'CHECK_IN/CHECK_OUT',
  `clock_time` datetime NOT NULL COMMENT '打卡时间',
  `location` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '打卡地点',
  `longitude` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '经度',
  `latitude` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '纬度',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `source` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'APP' COMMENT '打卡来源(APP/WECOM)',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_clock_emp_date` (`employee_id`,`clock_date`),
  KEY `idx_hrm_attendance_clock_created_at` (`created_at`),
  KEY `idx_hrm_attendance_clock_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='考勤打卡记录';

DROP TABLE IF EXISTS `hrm_attendance_summary`;

CREATE TABLE `hrm_attendance_summary` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `employee_id` bigint unsigned NOT NULL COMMENT '员工ID',
  `year_month` varchar(7) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '年月(2026-08)',
  `work_days` bigint DEFAULT '22' COMMENT '应出勤天数',
  `actual_days` bigint DEFAULT '0' COMMENT '实际出勤天数',
  `late_count` bigint DEFAULT '0' COMMENT '迟到次数',
  `early_count` bigint DEFAULT '0' COMMENT '早退次数',
  `absent_days` decimal(5,1) DEFAULT '0.0' COMMENT '缺勤天数',
  `leave_days` decimal(5,1) DEFAULT '0.0' COMMENT '请假天数',
  `overtime_hours` decimal(5,1) DEFAULT '0.0' COMMENT '加班时长',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_att_summary` (`employee_id`,`year_month`),
  KEY `idx_hrm_attendance_summary_created_at` (`created_at`),
  KEY `idx_hrm_attendance_summary_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='月度考勤汇总(定时任务生成或手动统计)';

DROP TABLE IF EXISTS `hrm_candidate`;

CREATE TABLE `hrm_candidate` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `job_id` bigint unsigned NOT NULL COMMENT '职位ID',
  `name` varchar(100) NOT NULL COMMENT '姓名',
  `phone` varchar(50) DEFAULT '' COMMENT '电话',
  `email` varchar(100) DEFAULT '' COMMENT '邮箱',
  `gender` varchar(10) DEFAULT '' COMMENT '性别',
  `age` int DEFAULT '0' COMMENT '年龄',
  `education` varchar(32) DEFAULT '' COMMENT '学历',
  `experience` varchar(100) DEFAULT '' COMMENT '工作年限',
  `company` varchar(200) DEFAULT '' COMMENT '当前公司',
  `resume_url` varchar(500) DEFAULT '' COMMENT '简历链接',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1新简历2筛选3面试4offer5录用6淘汰',
  `source` varchar(100) DEFAULT '' COMMENT '来源',
  `interview_date` varchar(32) DEFAULT '' COMMENT '面试时间',
  `remark` varchar(1000) DEFAULT '' COMMENT '备注',
  `evaluator_id` bigint unsigned DEFAULT NULL COMMENT '评估人ID',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_hrm_cand_job` (`job_id`),
  KEY `idx_hrm_cand_status` (`status`),
  KEY `idx_hrm_cand_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='HRM 招聘候选人';

