DROP TABLE IF EXISTS `hrm_employee`;

CREATE TABLE `hrm_employee` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `emp_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '员工工号',
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '姓名',
  `gender` tinyint DEFAULT '0' COMMENT '性别(0未知 1男 2女)',
  `phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '电话',
  `email` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮箱',
  `department_id` bigint unsigned NOT NULL COMMENT '部门ID',
  `position_id` bigint unsigned NOT NULL COMMENT '岗位ID',
  `user_id` bigint unsigned DEFAULT NULL COMMENT '关联系统用户ID',
  `entry_date` date DEFAULT NULL COMMENT '入职日期',
  `resign_date` date DEFAULT NULL COMMENT '离职日期',
  `status` tinyint DEFAULT '1' COMMENT '1在职 2试用 3离职',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
