  KEY `idx_hrm_employee_department_id` (`department_id`),
  KEY `idx_hrm_employee_position_id` (`position_id`),
  KEY `idx_hrm_employee_user_id` (`user_id`),
  KEY `idx_hrm_employee_status` (`status`),
  KEY `idx_hrm_employee_created_at` (`created_at`),
  KEY `idx_hrm_employee_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='员工档案';

