DROP TABLE IF EXISTS `hrm_job`;

CREATE TABLE `hrm_job` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `job_no` varchar(64) NOT NULL COMMENT '职位编号',
  `title` varchar(200) NOT NULL COMMENT '职位名称',
  `dept_id` bigint unsigned DEFAULT NULL COMMENT '部门ID',
  `dept_name` varchar(200) DEFAULT '' COMMENT '部门名称',
  `position_id` bigint unsigned DEFAULT NULL COMMENT '岗位ID',
  `headcount` int NOT NULL DEFAULT '1' COMMENT '招聘人数',
  `salary_range` varchar(100) DEFAULT '' COMMENT '薪资范围',
  `education` varchar(32) DEFAULT '' COMMENT '学历要求',
  `experience` varchar(100) DEFAULT '' COMMENT '经验要求',
  `description` varchar(2000) DEFAULT '' COMMENT '职位描述',
  `requirement` varchar(2000) DEFAULT '' COMMENT '任职要求',
  `hiring_manager_id` bigint unsigned DEFAULT NULL COMMENT '招聘负责人ID',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1草稿2招聘3暂停4关闭5满编',
  `publish_date` date DEFAULT NULL COMMENT '发布日期',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_hrm_job_no` (`job_no`),
  KEY `idx_hrm_job_dept` (`dept_id`),
  KEY `idx_hrm_job_status` (`status`),
  KEY `idx_hrm_job_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='HRM 招聘职位';

