DROP TABLE IF EXISTS `hrm_overtime`;

CREATE TABLE `hrm_overtime` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `overtime_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '加班单号',
  `employee_id` bigint unsigned NOT NULL COMMENT '员工ID',
  `start_date` datetime NOT NULL COMMENT '加班开始时间',
  `end_date` datetime NOT NULL COMMENT '加班结束时间',
  `duration_hours` decimal(5,1) NOT NULL COMMENT '加班时长(小时)',
  `reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '加班事由',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING' COMMENT '审批状态',
  `approver_id` bigint unsigned DEFAULT NULL COMMENT '审批人ID',
  `approve_time` datetime DEFAULT NULL COMMENT '审批时间',
  `approve_remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批意见',
  `compensate_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'PAY' COMMENT '补偿方式 PAY加班费/TO调休',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_hrm_overtime_employee_id` (`employee_id`),
  KEY `idx_hrm_overtime_status` (`status`),
  KEY `idx_hrm_overtime_created_at` (`created_at`),
  KEY `idx_hrm_overtime_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='加班单';

DROP TABLE IF EXISTS `hrm_payroll`;

CREATE TABLE `hrm_payroll` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `employee_id` bigint unsigned NOT NULL COMMENT '员工ID',
  `year_month` varchar(7) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '年月(2026-08)',
  `base_salary` decimal(12,2) DEFAULT NULL COMMENT '基本工资',
  `position_allow` decimal(12,2) DEFAULT NULL COMMENT '岗位津贴',
  `performance_allow` decimal(12,2) DEFAULT NULL COMMENT '绩效津贴',
  `other_allow` decimal(12,2) DEFAULT NULL COMMENT '其他补贴(餐补/交通)',
  `overtime_pay` decimal(12,2) DEFAULT NULL COMMENT '加班费',
  `gross_pay` decimal(12,2) DEFAULT NULL COMMENT '应发合计',
  `social_ins_deduction` decimal(12,2) DEFAULT NULL COMMENT '社保扣除(个人)',
  `housing_fund_deduction` decimal(12,2) DEFAULT NULL COMMENT '公积金扣除(个人)',
  `absence_deduction` decimal(12,2) DEFAULT NULL COMMENT '缺勤扣除',
  `taxable_income` decimal(12,2) DEFAULT NULL COMMENT '应纳税所得额',
  `tax` decimal(12,2) DEFAULT NULL COMMENT '个人所得税',
  `net_pay` decimal(12,2) DEFAULT NULL COMMENT '实发合计(税后)',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'DRAFT' COMMENT 'DRAFT/CONFIRMED/PAID',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_payroll` (`employee_id`,`year_month`),
  KEY `idx_hrm_payroll_status` (`status`),
  KEY `idx_hrm_payroll_created_at` (`created_at`),
  KEY `idx_hrm_payroll_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工资条(月度,每员工每月一条)';

DROP TABLE IF EXISTS `hrm_perf_item`;

CREATE TABLE `hrm_perf_item` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `perf_id` bigint unsigned NOT NULL COMMENT '考核ID',
  `item_name` varchar(200) NOT NULL COMMENT '指标名称',
  `weight` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '权重(%)',
  `target_desc` varchar(500) DEFAULT '' COMMENT '目标说明',
  `self_score` decimal(5,1) NOT NULL DEFAULT '0.0' COMMENT '自评得分',
  `review_score` decimal(5,1) NOT NULL DEFAULT '0.0' COMMENT '上级评分',
  `remark` varchar(500) DEFAULT '' COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_hrm_perfitem_perf` (`perf_id`),
  KEY `idx_hrm_perfitem_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='HRM 考核指标项';

