DROP TABLE IF EXISTS `hrm_performance`;

CREATE TABLE `hrm_performance` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `perf_no` varchar(64) NOT NULL COMMENT '考核编号',
  `title` varchar(200) NOT NULL COMMENT '考核标题',
  `employee_id` bigint unsigned NOT NULL COMMENT '被考核人ID',
  `employee_name` varchar(200) DEFAULT '' COMMENT '员工姓名',
  `dept_id` bigint unsigned DEFAULT NULL COMMENT '部门ID',
  `dept_name` varchar(200) DEFAULT '' COMMENT '部门名称',
  `period` varchar(20) DEFAULT '' COMMENT '考核周期',
  `start_date` date NOT NULL COMMENT '考核开始',
  `end_date` date NOT NULL COMMENT '考核结束',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1草稿2进行3自评完成4评审中5完成6取消',
  `reviewer_id` bigint unsigned DEFAULT NULL COMMENT '评审人ID',
  `self_score` decimal(5,1) NOT NULL DEFAULT '0.0' COMMENT '自评得分',
  `self_comment` varchar(2000) DEFAULT '' COMMENT '自评说明',
  `self_time` datetime DEFAULT NULL COMMENT '自评时间',
  `review_score` decimal(5,1) NOT NULL DEFAULT '0.0' COMMENT '上级评分',
  `review_comment` varchar(2000) DEFAULT '' COMMENT '评审意见',
  `review_time` datetime DEFAULT NULL COMMENT '评审时间',
  `final_score` decimal(5,1) NOT NULL DEFAULT '0.0' COMMENT '最终得分',
  `grade` varchar(10) DEFAULT '' COMMENT '等级(A/B/C/D)',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_hrm_perf_no` (`perf_no`),
  KEY `idx_hrm_perf_employee` (`employee_id`),
  KEY `idx_hrm_perf_dept` (`dept_id`),
  KEY `idx_hrm_perf_period` (`period`),
  KEY `idx_hrm_perf_status` (`status`),
  KEY `idx_hrm_perf_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='HRM 绩效考核';

