  KEY `idx_kb_doc_status` (`status`),
  KEY `idx_kb_doc_creator` (`creator_id`),
  KEY `idx_kb_doc_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='知识库文档';

