DROP TABLE IF EXISTS `kb_version`;

CREATE TABLE `kb_version` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `document_id` bigint unsigned NOT NULL COMMENT '文档ID',
  `content` longtext COMMENT '版本内容快照',
  `editor_id` bigint unsigned NOT NULL COMMENT '编辑人ID',
  `version_note` varchar(200) DEFAULT '' COMMENT '版本说明',
  `version_number` int NOT NULL DEFAULT '1' COMMENT '版本号(递增)',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_kb_version_doc` (`document_id`),
  KEY `idx_kb_version_editor` (`editor_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='知识库版本历史';

DROP TABLE IF EXISTS `lead_field`;

CREATE TABLE `lead_field` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID',
  `resource_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '线索ID',
  `field_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段ID',
  `field_value` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段值',
  PRIMARY KEY (`id`),
  KEY `idx_lead_rfv` (`resource_id`,`field_id`,`field_value`),
  KEY `idx_lead_field_field_id` (`field_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='线索自定义字段值(单值)';

DROP TABLE IF EXISTS `lead_field_blob`;

CREATE TABLE `lead_field_blob` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID',
  `resource_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '线索ID',
  `field_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段定义ID(关联sys_module_field)',
  `field_value` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段值(大文本)',
  PRIMARY KEY (`id`),
  KEY `idx_lead_field_blob_resource_id` (`resource_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='线索自定义字段大值';

DROP TABLE IF EXISTS `mall_order`;

CREATE TABLE `mall_order` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单号(MO+日期+序号)',
  `customer_id` bigint unsigned DEFAULT NULL COMMENT '关联客户ID',
  `contact_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '收货人姓名',
  `contact_phone` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联系电话',
  `address` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '收货地址',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `total_quantity` decimal(14,3) NOT NULL DEFAULT '0.000' COMMENT '总数量',
  `total_amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '总金额',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1待处理 2已确认 3已完成 4已取消',
  `psi_order_id` bigint unsigned DEFAULT NULL COMMENT '关联PSI销售单ID',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_no` (`order_no`),
  KEY `idx_mall_order_customer` (`customer_id`),
  KEY `idx_mall_order_phone` (`contact_phone`),
  KEY `idx_mall_order_status` (`status`),
  KEY `idx_mall_order_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='商城订单';

DROP TABLE IF EXISTS `mall_order_item`;

CREATE TABLE `mall_order_item` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL COMMENT '订单ID',
  `product_id` bigint unsigned NOT NULL COMMENT '商品ID(crm_product)',
  `sku_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '规格SKU ID',
  `product_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品名称快照',
  `spec` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '规格描述快照',
  `quantity` decimal(14,3) NOT NULL COMMENT '数量',
  `unit_price` decimal(14,2) NOT NULL COMMENT '单价快照',
  `amount` decimal(14,2) NOT NULL COMMENT '金额',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_mall_item_order` (`order_id`),
  KEY `idx_mall_item_deleted` (`deleted_at`),
  KEY `idx_mall_order_item_sku_id` (`sku_id`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='商城订单明细';

INSERT INTO `mall_order_item` (`id`, `order_id`, `product_id`, `sku_id`, `product_name`, `spec`, `quantity`, `unit_price`, `amount`, `created_at`, `updated_at`, `deleted_at`) VALUES (7, 7, 14, 3, '回归商品B', '', 1.000, 150.00, 150.00, '2026-08-28 21:22:17.450', '2026-08-28 21:22:17.450', NULL);

DROP TABLE IF EXISTS `marketing_account`;

CREATE TABLE `marketing_account` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '账号备注名',
  `channel` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'oceanengine' COMMENT '渠道(oceanengine巨量引擎)',
  `app_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '开放平台应用ID',
  `app_secret` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '应用Secret(脱敏不回显)',
  `access_token` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '访问令牌(约24h)',
  `refresh_token` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '刷新令牌(约30d)',
  `token_expires_at` datetime DEFAULT NULL COMMENT 'access_token过期时间',
  `refresh_expires_at` datetime DEFAULT NULL COMMENT 'refresh_token过期时间',
  `advertiser_ids` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '已授权广告主ID(逗号分隔)',
  `status` tinyint DEFAULT '0' COMMENT '0待授权 1已授权 2授权失效',
  `enabled` tinyint DEFAULT '1' COMMENT '1启用 0停用',
  `last_sync_at` datetime DEFAULT NULL COMMENT '上次线索同步游标时间',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_marketing_account_status` (`status`,`enabled`),
  KEY `idx_marketing_account_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='营销渠道账号(巨量引擎)';

INSERT INTO `marketing_account` (`id`, `name`, `channel`, `app_id`, `app_secret`, `access_token`, `refresh_token`, `token_expires_at`, `refresh_expires_at`, `advertiser_ids`, `status`, `enabled`, `last_sync_at`, `created_at`, `updated_at`, `deleted_at`) VALUES (1, '部署验证-临时账号', 'oceanengine', 'app_verify_123', 'secret_verify_456', '', '', NULL, NULL, '', 0, 1, NULL, '2026-08-19 17:46:25.056', '2026-08-19 17:46:25.056', '2026-08-19 17:46:25.553');

DROP TABLE IF EXISTS `marketing_lead_log`;

CREATE TABLE `marketing_lead_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `account_id` bigint unsigned NOT NULL COMMENT '渠道账号ID',
  `external_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '外部线索ID(飞鱼clue_id)',
  `lead_id` bigint unsigned DEFAULT NULL COMMENT '入库后的crm_lead.id(重复/失败为NULL)',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '姓名',
  `phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '手机号(可能是虚拟号)',
  `company` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公司',
  `campaign_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '广告计划名称',
  `ad_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '广告名称',
  `lead_create_time` datetime DEFAULT NULL COMMENT '留资时间',
  `status` tinyint NOT NULL COMMENT '1已入库 2重复跳过 3失败',
  `detail` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '说明(重复/失败原因)',
  `raw` json DEFAULT NULL COMMENT '原始报文(排查用)',
  `created_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_marketing_lead_log_ext` (`account_id`,`external_id`),
  KEY `idx_marketing_lead_log_status` (`status`),
  KEY `idx_marketing_lead_log_phone` (`phone`),
  KEY `idx_marketing_lead_log_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='营销线索同步日志';

DROP TABLE IF EXISTS `oa_business_trip`;

CREATE TABLE `oa_business_trip` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `trip_no` varchar(64) NOT NULL COMMENT '出差单号',
  `title` varchar(200) NOT NULL COMMENT '出差标题',
  `applicant_id` bigint unsigned NOT NULL COMMENT '申请人ID',
  `dept_id` bigint unsigned DEFAULT NULL COMMENT '部门ID',
  `destination` varchar(200) NOT NULL COMMENT '目的地',
  `purpose` varchar(500) DEFAULT '' COMMENT '出差目的',
  `start_date` date NOT NULL COMMENT '出发日期',
  `end_date` date NOT NULL COMMENT '返回日期',
  `transport` varchar(32) DEFAULT '' COMMENT '交通方式',
  `budget_amount` varchar(32) DEFAULT '' COMMENT '预算金额',
  `description` varchar(1000) DEFAULT '' COMMENT '备注说明',
  `approval_status` varchar(20) NOT NULL DEFAULT 'NONE' COMMENT '审批状态',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oa_trip_no` (`trip_no`),
  KEY `idx_oa_trip_applicant` (`applicant_id`),
  KEY `idx_oa_trip_approval` (`approval_status`),
  KEY `idx_oa_trip_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='OA 出差申请';

