DROP TABLE IF EXISTS `oa_loan`;

CREATE TABLE `oa_loan` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `loan_no` varchar(64) NOT NULL COMMENT '借款单号',
  `title` varchar(200) NOT NULL COMMENT '借款标题',
  `applicant_id` bigint unsigned NOT NULL COMMENT '借款人ID',
  `dept_id` bigint unsigned DEFAULT NULL COMMENT '部门ID',
  `loan_type` varchar(32) NOT NULL COMMENT '借款类型',
  `amount` varchar(32) NOT NULL COMMENT '借款金额',
  `expected_date` date DEFAULT NULL COMMENT '预计还款日期',
  `reason` varchar(500) DEFAULT '' COMMENT '借款事由',
  `approval_status` varchar(20) NOT NULL DEFAULT 'NONE' COMMENT '审批状态',
  `repaid_status` tinyint NOT NULL DEFAULT '0' COMMENT '还款状态(0未还1部分2已还清)',
  `repaid_amount` varchar(32) NOT NULL DEFAULT '0' COMMENT '已还金额',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oa_loan_no` (`loan_no`),
  KEY `idx_oa_loan_applicant` (`applicant_id`),
  KEY `idx_oa_loan_type` (`loan_type`),
  KEY `idx_oa_loan_approval` (`approval_status`),
  KEY `idx_oa_loan_repaid` (`repaid_status`),
  KEY `idx_oa_loan_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='OA 借款/备用金';

INSERT INTO `oa_loan` (`id`, `loan_no`, `title`, `applicant_id`, `dept_id`, `loan_type`, `amount`, `expected_date`, `reason`, `approval_status`, `repaid_status`, `repaid_amount`, `created_at`, `updated_at`, `deleted_at`) VALUES (1, 'JK20260806001', '差旅借支-上海出差', 1, NULL, '差旅借支', '3000', '2026-08-31', '出差备用', 'APPROVED', 2, '3000', '2026-08-06 22:13:11.276', '2026-08-13 17:12:08.863', NULL), (2, 'JK20260819001', '1', 1, NULL, '备用金', '11', '2026-08-19', '', 'APPROVED', 2, '11', '2026-08-19 17:03:00.440', '2026-08-19 17:15:41.409', NULL), (3, 'JK20260819002', '2', 1, NULL, '个人借款', '22', '2026-08-21', '', 'NONE', 0, '0', '2026-08-19 17:10:24.230', '2026-08-19 17:10:24.230', '2026-08-19 17:15:48.035');

DROP TABLE IF EXISTS `oa_meeting_booking`;

CREATE TABLE `oa_meeting_booking` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `booking_no` varchar(64) NOT NULL COMMENT '预订单号',
  `title` varchar(200) NOT NULL COMMENT '会议标题',
  `room_id` bigint unsigned NOT NULL COMMENT '会议室ID',
  `organizer_id` bigint unsigned NOT NULL COMMENT '预订人ID',
  `dept_id` bigint unsigned DEFAULT NULL COMMENT '部门ID',
  `start_time` datetime NOT NULL COMMENT '开始时间',
  `end_time` datetime NOT NULL COMMENT '结束时间',
  `attendees` int NOT NULL DEFAULT '0' COMMENT '参会人数',
  `topic` varchar(500) DEFAULT '' COMMENT '会议主题/议程',
  `approval_status` varchar(20) NOT NULL DEFAULT 'NONE' COMMENT '审批状态(NONE/APPROVING/APPROVED/REJECTED/REVOKED)',
  `remark` varchar(500) DEFAULT '' COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oa_meeting_booking_no` (`booking_no`),
  KEY `idx_oa_meeting_booking_room` (`room_id`),
  KEY `idx_oa_meeting_booking_organizer` (`organizer_id`),
  KEY `idx_oa_meeting_booking_approval` (`approval_status`),
  KEY `idx_oa_meeting_booking_time` (`start_time`,`end_time`),
  KEY `idx_oa_meeting_booking_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='OA 会议预订';

