DROP TABLE IF EXISTS `oa_notice`;

CREATE TABLE `oa_notice` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `content` text COLLATE utf8mb4_unicode_ci COMMENT '内容',
  `type` tinyint DEFAULT '1' COMMENT '类型(1通知 2公告)',
  `status` tinyint DEFAULT '0' COMMENT '状态(0草稿 1发布)',
  `publish_time` datetime DEFAULT NULL COMMENT '发布时间',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_sys_notice_type` (`type`),
  KEY `idx_sys_notice_status` (`status`),
  KEY `idx_sys_notice_publish_time` (`publish_time`),
  KEY `idx_sys_notice_created_at` (`created_at`),
  KEY `idx_sys_notice_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='公告通知';

