DROP TABLE IF EXISTS `proj_project`;

CREATE TABLE `proj_project` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `project_no` varchar(64) NOT NULL COMMENT '项目编号',
  `name` varchar(200) NOT NULL COMMENT '项目名称',
  `description` varchar(2000) DEFAULT '' COMMENT '项目描述',
  `customer_id` bigint unsigned DEFAULT NULL COMMENT '关联客户ID',
  `customer_name` varchar(200) DEFAULT '' COMMENT '客户名称',
  `contract_id` bigint unsigned DEFAULT NULL COMMENT '关联合同ID',
  `manager_id` bigint unsigned DEFAULT NULL COMMENT '项目经理ID',
  `member_ids` varchar(500) DEFAULT '' COMMENT '成员ID(逗号分隔)',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1规划2进行3暂停4完成5取消',
  `priority` tinyint NOT NULL DEFAULT '2' COMMENT '1低2中3高4紧急',
  `start_date` date DEFAULT NULL COMMENT '开始日期',
  `end_date` date DEFAULT NULL COMMENT '计划完成日期',
  `progress` tinyint NOT NULL DEFAULT '0' COMMENT '进度(0-100)',
  `tags` varchar(200) DEFAULT '' COMMENT '标签',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_no` (`project_no`),
  KEY `idx_proj_customer` (`customer_id`),
  KEY `idx_proj_contract` (`contract_id`),
  KEY `idx_proj_manager` (`manager_id`),
  KEY `idx_proj_status` (`status`),
  KEY `idx_proj_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='项目';

