  KEY `idx_psi_purchase_order_created_at` (`created_at`),
  KEY `idx_psi_purchase_order_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='采购订单';

