  KEY `idx_psi_purchase_order_detail_product_id` (`product_id`),
  KEY `idx_psi_purchase_order_detail_created_at` (`created_at`),
  KEY `idx_psi_purchase_order_detail_deleted_at` (`deleted_at`),
