DROP TABLE IF EXISTS `psi_stock`;

CREATE TABLE `psi_stock` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `product_id` bigint unsigned NOT NULL COMMENT '商品ID(引用crm_product.id)',
  `sku_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '规格SKU ID',
  `warehouse_id` bigint unsigned NOT NULL COMMENT '仓库ID',
  `quantity` decimal(14,3) DEFAULT '0.000' COMMENT '在手数量',
  `safety_stock` decimal(14,3) DEFAULT '0.000' COMMENT '安全库存(预警阈值)',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sku_warehouse` (`sku_id`,`warehouse_id`),
  KEY `idx_psi_stock_product_id` (`product_id`),
  KEY `idx_psi_stock_warehouse_id` (`warehouse_id`),
  KEY `idx_psi_stock_created_at` (`created_at`),
  KEY `idx_psi_stock_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='库存结余(按 商品+仓库 维度)';

