  KEY `idx_psi_stock_in_order_operator_id` (`operator_id`),
  KEY `idx_psi_stock_in_order_created_at` (`created_at`),
  KEY `idx_psi_stock_in_order_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='其他入库单(盘盈/赠品/期初/其他)';

