DROP TABLE IF EXISTS `stage_config`;

CREATE TABLE `stage_config` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `biz_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型(OPPORTUNITY/CONTRACT)',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '配置名称',
  `stages_json` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '阶段数组JSON',
  `enabled` tinyint DEFAULT '1' COMMENT '是否启用',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_stage_config_biz_type` (`biz_type`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='阶段配置';

INSERT INTO `stage_config` (`id`, `biz_type`, `name`, `stages_json`, `enabled`) VALUES (1, 'OPPORTUNITY', '商机销售漏斗', '[{"key":"PROSPECTING","label":"初步接触","color":"#909399","sort":0,"probability":10},{"key":"ANALYSIS","label":"需求分析","color":"#409EFF","sort":1,"probability":25},{"key":"PROPOSAL","label":"方案报价","color":"#409EFF","sort":2,"probability":50},{"key":"NEGOTIATION","label":"谈判","color":"#E6A23C","sort":3,"probability":70},{"key":"WON","label":"已成交","color":"#67C23A","sort":4,"probability":100},{"key":"LOST","label":"已丢失","color":"#F56C6C","sort":5,"probability":0}]', 1), (2, 'CONTRACT', '合同阶段', '[{"key":"DRAFT","label":"草稿","color":"#909399","sort":0,"probability":0},{"key":"APPROVAL","label":"审批中","color":"#E6A23C","sort":1,"probability":30},{"key":"SIGNED","label":"已签订","color":"#409EFF","sort":2,"probability":60},{"key":"EXECUTING","label":"执行中","color":"#409EFF","sort":3,"probability":80},{"key":"COMPLETED","label":"已完成","color":"#67C23A","sort":4,"probability":100},{"key":"TERMINATED","label":"已终止","color":"#F56C6C","sort":5,"probability":0}]', 1);

DROP TABLE IF EXISTS `stage_record`;

CREATE TABLE `stage_record` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `biz_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型',
  `resource_id` bigint unsigned NOT NULL COMMENT '资源ID(商机/合同ID)',
  `from_stage` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原阶段(首次进入为空)',
  `to_stage` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '新阶段',
  `operator_id` bigint unsigned NOT NULL COMMENT '操作人',
  `reason` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原因',
  PRIMARY KEY (`id`),
  KEY `idx_stage_record_biz_type` (`biz_type`),
  KEY `idx_stage_record_resource_id` (`resource_id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='阶段变更记录(追加写,不软删除)';

INSERT INTO `stage_record` (`id`, `biz_type`, `resource_id`, `from_stage`, `to_stage`, `operator_id`, `reason`) VALUES (1, 'OPPORTUNITY', 1, 'PROSPECTING', 'NEGOTIATION', 1, '谈判'), (2, 'OPPORTUNITY', 1, 'NEGOTIATION', 'WON', 1, ''), (3, 'OPPORTUNITY', 12, 'PROSPECTING', 'WON', 1, '测试阶段流转'), (4, 'OPPORTUNITY', 12, 'WON', 'LOST', 1, '测试输单'), (5, 'OPPORTUNITY', 13, 'PROSPECTING', 'ANALYSIS', 1, '走查测试流转'), (6, 'OPPORTUNITY', 14, 'PROSPECTING', 'ANALYSIS', 1, ''), (7, 'OPPORTUNITY', 14, 'ANALYSIS', 'PROSPECTING', 1, '');

DROP TABLE IF EXISTS `sys_api`;

CREATE TABLE `sys_api` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `path` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '接口路径',
  `method` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'HTTP方法',
  `group` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '接口分组/模块',
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_sys_api_created_at` (`created_at`),
  KEY `idx_sys_api_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=706 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='接口注册表';

