DROP TABLE IF EXISTS `sys_api_key`;

CREATE TABLE `sys_api_key` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint unsigned NOT NULL COMMENT '关联用户ID',
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Key名称(如''我的CLI'')',
  `key_prefix` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '前缀(qzt_)',
  `key_hash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SHA256 hash',
  `last_used_at` datetime DEFAULT NULL COMMENT '最后使用时间',
  `last_used_ip` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最后使用IP',
  `expires_at` datetime DEFAULT NULL COMMENT '过期时间(空=永不过期)',
  `status` tinyint DEFAULT '1' COMMENT '1启用0禁用',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  `toolsets` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '可用工具集(逗号分隔,空=全部)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_sys_api_key_key_hash` (`key_hash`),
  KEY `idx_sys_api_key_user_id` (`user_id`),
  KEY `idx_sys_api_key_status` (`status`),
  KEY `idx_sys_api_key_created_at` (`created_at`),
  KEY `idx_sys_api_key_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户 API Key';

