DROP TABLE IF EXISTS `sys_config`;

CREATE TABLE `sys_config` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `group` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分组',
  `key` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '配置键',
  `name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '显示名',
  `value` text COLLATE utf8mb4_unicode_ci COMMENT '值(统一字符串存储)',
  `type` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'string' COMMENT 'string/int/bool/float/json/text/select',
  `options` text COLLATE utf8mb4_unicode_ci COMMENT 'select 选项或校验规则(JSON)',
  `is_public` tinyint(1) DEFAULT '0' COMMENT '是否免鉴权可读',
  `editable` tinyint(1) DEFAULT '1' COMMENT '是否允许后台编辑',
  `builtin` tinyint(1) DEFAULT '0' COMMENT '内置(不可删除)',
  `sort` bigint DEFAULT '0' COMMENT '排序号',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_sys_config_key` (`key`),
  KEY `idx_sys_config_group` (`group`),
  KEY `idx_sys_config_created_at` (`created_at`),
  KEY `idx_sys_config_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统配置(运行时参数键值对)';

