DROP TABLE IF EXISTS `sys_oauth_config`;

CREATE TABLE `sys_oauth_config` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `provider` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '渠道(wecom/ding/feishu)',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '显示名称(如''企业微信扫码登录'')',
  `enabled` tinyint DEFAULT '0' COMMENT '是否启用(1启用0禁用)',
  `app_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '应用ID(corp_id/app_key)',
  `app_secret` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '应用Secret(脱敏,不返回)',
  `agent_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'AgentID(企业微信用)',
  `redirect_uri` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '扫码登录回调地址',
  `extra` text COLLATE utf8mb4_unicode_ci COMMENT '扩展配置JSON',
  `sort` bigint DEFAULT '0' COMMENT '排序号',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_sys_oauth_config_provider` (`provider`),
  KEY `idx_sys_oauth_config_enabled` (`enabled`),
  KEY `idx_sys_oauth_config_created_at` (`created_at`),
  KEY `idx_sys_oauth_config_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='第三方登录配置';

INSERT INTO `sys_oauth_config` (`id`, `provider`, `name`, `enabled`, `app_id`, `app_secret`, `agent_id`, `redirect_uri`, `extra`, `sort`, `remark`, `created_at`, `updated_at`, `deleted_at`) VALUES (2, 'wecom', '企业微信', 1, 'ww6a76a1503485c158', '', '1000009', 'https://m.devlovecode.com/auth/wecom/bind', '', 0, '', '2026-08-11 11:09:53.493', '2026-08-17 19:57:57.741', NULL);

DROP TABLE IF EXISTS `sys_operation_log`;

CREATE TABLE `sys_operation_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `trace_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '链路ID，关联应用日志',
  `user_id` bigint unsigned DEFAULT NULL COMMENT '操作人ID',
  `username` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作人用户名(冗余存储)',
  `role_codes` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作人角色快照(逗号分隔)',
  `module` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所属模块(取自sys_api.group)',
  `action` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作描述(取自sys_api.description)',
  `method` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'HTTP方法',
  `route` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '路由模板',
  `path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实际请求路径',
  `target_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '目标资源ID',
  `req_params` text COLLATE utf8mb4_unicode_ci COMMENT '请求参数(脱敏+截断)',
  `resp_params` text COLLATE utf8mb4_unicode_ci COMMENT '响应参数(脱敏+截断)',
  `status` bigint DEFAULT NULL COMMENT 'HTTP状态码',
  `biz_code` bigint DEFAULT NULL COMMENT '业务返回码',
  `success` tinyint(1) DEFAULT NULL COMMENT '是否成功',
  `error_msg` text COLLATE utf8mb4_unicode_ci COMMENT '失败信息',
  `client_ip` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户端IP',
  `user_agent` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'User-Agent',
  `latency_ms` bigint DEFAULT NULL COMMENT '耗时(毫秒)',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_sys_operation_log_user_id` (`user_id`),
  KEY `idx_sys_operation_log_module` (`module`),
  KEY `idx_sys_operation_log_success` (`success`),
  KEY `idx_sys_operation_log_client_ip` (`client_ip`),
  KEY `idx_sys_operation_log_created_at` (`created_at`),
  KEY `idx_sys_operation_log_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=3320 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='操作审计日志，记录一次写操作（或登录/登出）';



































DROP TABLE IF EXISTS `sys_role`;

CREATE TABLE `sys_role` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '名称',
  `code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '编码',
  `sort` bigint DEFAULT '0' COMMENT '排序号',
  `status` tinyint DEFAULT '1' COMMENT '1-正常 0-禁用',
  `data_scope` tinyint NOT NULL DEFAULT '1' COMMENT '数据权限范围 1全部 3本部门 4本部门及子部门 5仅本人',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_sys_role_code` (`code`),
  KEY `idx_sys_role_created_at` (`created_at`),
  KEY `idx_sys_role_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='角色';

