DROP TABLE IF EXISTS `sys_role_menu`;

CREATE TABLE `sys_role_menu` (
  `sys_role_id` bigint unsigned NOT NULL COMMENT '角色ID',
  `sys_menu_id` bigint unsigned NOT NULL COMMENT '菜单ID',
  PRIMARY KEY (`sys_role_id`,`sys_menu_id`),
  KEY `fk_sys_role_menu_sys_menu` (`sys_menu_id`),
  CONSTRAINT `fk_sys_role_menu_sys_menu` FOREIGN KEY (`sys_menu_id`) REFERENCES `sys_menu` (`id`),
  CONSTRAINT `fk_sys_role_menu_sys_role` FOREIGN KEY (`sys_role_id`) REFERENCES `sys_role` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='角色-菜单关联表';

