DROP TABLE IF EXISTS `sys_site_config`;

CREATE TABLE `sys_site_config` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `site_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '站点名称(企业名)',
  `logo_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Logo图片URL',
  `favicon_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Favicon图标URL',
  `hero_title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首页Hero大标题',
  `hero_subtitle` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首页Hero副标题',
  `hero_badge` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首页Hero小标签',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '站点描述(SEO meta description)',
  `theme` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '前台主题包(dark-tech/light-clean)',
  `stats_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '首页数字带JSON',
  `modules_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '首页模块墙JSON',
  `modules_badge` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首页优势区块徽章',
  `modules_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首页优势区块标题',
  `modules_desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首页优势区块副标题',
  `cta_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首页底部CTA标题',
  `cta_highlight` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首页底部CTA高亮词',
  `cta_subtitle` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首页底部CTA副标题',
  `contact_phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话',
  `contact_email` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系邮箱',
  `contact_address` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公司地址',
  `work_hours` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工作时间(如 周一至周五 9:00-18:00)',
  `icp_beian` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ICP备案号(如 京ICP备xxxxxxxx号)',
  `public_security_beian` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公安备案号',
  `public_security_beian_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公安备案跳转链接',
  `keywords` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SEO关键词(逗号分隔)',
  `analytics_code` text COLLATE utf8mb4_unicode_ci COMMENT '统计代码(GA/百度统计等JS)',
  `copyright` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '版权声明(如 © 2024 某某科技有限公司)',
  `mcp_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'MCP服务地址',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_sys_site_config_created_at` (`created_at`),
  KEY `idx_sys_site_config_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='站点信息配置';

INSERT INTO `sys_site_config` (`id`, `site_name`, `logo_url`, `favicon_url`, `hero_title`, `hero_subtitle`, `hero_badge`, `description`, `theme`, `stats_json`, `modules_json`, `modules_badge`, `modules_title`, `modules_desc`, `cta_title`, `cta_highlight`, `cta_subtitle`, `contact_phone`, `contact_email`, `contact_address`, `work_hours`, `icp_beian`, `public_security_beian`, `public_security_beian_url`, `keywords`, `analytics_code`, `copyright`, `mcp_url`, `created_at`, `updated_at`, `deleted_at`) VALUES (1, '行简 · 一站式企业管理平台', 'https://cdn.devlovecode.com/site/c1693b647797163b460756a522d041fb.png', '', '一个系统，管好企业的全部业务', '行简 = CRM + 审批流 + 进销存 + 财务 + HRM + OA。13 个模块一体化，私有化部署，数据完全归企业所有。告别在多个 SaaS 之间来回切换的割裂体验。', '私有化部署 · 数据归企业所有', '行简是一体化企业管理平台，私有化部署，数据归企业所有。涵盖 CRM 客户管理、审批流、进销存、财务、HRM、OA 等 13 个模块，支持 AI(MCP) 直连操作业务数据。', 'light-clean', '[{"num":"13","label":"业务模块一体化"},{"num":"411+","label":"API 接口"},{"num":"123","label":"数据表架构"}]', '[{"icon":"users","name":"CRM 客户管理","desc":"从线索到回款, 客户全生命周期在一个地方闭环。","pills":["线索","公海","商机","合同","回款"],"big":true},{"icon":"fileCheck","name":"审批流","desc":"自定义表单与流程引擎"},{"icon":"box","name":"进销存","desc":"采购·销售·库存一体"},{"icon":"wallet","name":"财务","desc":"收支·发票·资金流水"},{"icon":"idCard","name":"HRM 人事","desc":"组织·考勤·薪酬"},{"icon":"calendar","name":"OA 办公","desc":"公告·日程·报销借款"},{"icon":"kanban","name":"项目管理","desc":"任务·看板·里程碑"},{"icon":"book","name":"知识库","desc":"文档沉淀与协作"},{"icon":"cloud","name":"企业云盘","desc":"文件统一存储管理"},{"icon":"megaphone","name":"营销线索","desc":"抖音飞鱼线索自动入库"},{"icon":"bag","name":"独立商城","desc":"下单自动生成销售单"},{"icon":"globe","name":"CMS 官网","desc":"官网内容与页面管理"},{"icon":"sparkles","name":"AI 集成 (MCP)","desc":"411+ API 全量开放给 AI 助手"}]', '全模块一体化', '一个系统, 装下企业的全部业务', '模块自由组合, 数据天然打通 — 告别在多个系统之间来回切换', '准备把业务搬进', '一个系统 ?', '私有化部署, 数据完全归企业所有。留下联系方式, 我们来聊聊您的场景。', '15139960649', 'shichenyang@devlovecode.com', '河南省洛阳市', '周一至周五 9:00-18:00', '豫ICP备2024074107号-2', '', '', '私有化部署ERP,一体化企业管理平台,CRM客户管理,进销存系统,审批流程,企业管理软件,开源ERP,AI原生ERP,MCP协议', '', '© 2026 河南爱编程网络科技有限公司. All rights reserved.', 'https://devlovecode.com/mcp', '2026-08-04 10:51:25.610', '2026-08-21 12:28:15.069', NULL);

DROP TABLE IF EXISTS `sys_storage_config`;

CREATE TABLE `sys_storage_config` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `driver` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'local' COMMENT '存储驱动(local/oss)',
  `local_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT './storage/uploads' COMMENT '本地存储根目录',
  `resource_domain` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '本地资源访问域名',
  `oss_endpoint` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'OSS Endpoint',
  `oss_access_key_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'OSS AccessKeyID',
  `oss_access_key_secret` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'OSS AccessKeySecret(脱敏不返回)',
  `oss_bucket_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'OSS Bucket名称',
  `oss_custom_domain` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'OSS 自定义域名/CDN',
  `max_upload_mb` bigint DEFAULT '20' COMMENT '单文件大小上限(MB)',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_sys_storage_config_created_at` (`created_at`),
  KEY `idx_sys_storage_config_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='存储配置(本地/OSS)';

INSERT INTO `sys_storage_config` (`id`, `driver`, `local_path`, `resource_domain`, `oss_endpoint`, `oss_access_key_id`, `oss_access_key_secret`, `oss_bucket_name`, `oss_custom_domain`, `max_upload_mb`, `remark`, `created_at`, `updated_at`, `deleted_at`) VALUES (1, 'oss', './storage/uploads', 'https://cdn.devlovecode.com', 'oss-cn-hangzhou.aliyuncs.com', '<your_oss_access_key_id>', '<your_oss_access_key_secret>', 'yt4j', 'https://cdn.devlovecode.com', 20, '后台修改测试', '2026-08-04 03:40:27.089', '2026-08-05 08:51:24.892', NULL);

DROP TABLE IF EXISTS `sys_user`;

CREATE TABLE `sys_user` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `username` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户名(登录账号)',
  `password` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '密码',
  `nickname` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '昵称',
  `dept_id` bigint unsigned DEFAULT NULL COMMENT '部门ID(关联hrm_department)',
  `leader_id` bigint unsigned DEFAULT NULL COMMENT '直属上级ID(关联sys_user,审批SUPERIOR用)',
  `avatar` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '头像',
  `email` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮箱',
  `phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '手机号',
  `status` tinyint DEFAULT '1' COMMENT '1-正常 0-禁用',
  `token_version` bigint DEFAULT '0' COMMENT '会话版本，自增使旧 token 失效',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  `wecom_user_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '企业微信UserID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_sys_user_username` (`username`),
  KEY `idx_sys_user_created_at` (`created_at`),
  KEY `idx_sys_user_deleted_at` (`deleted_at`),
  KEY `idx_sys_user_wecom_user_id` (`wecom_user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统用户';

